  str_pet_equip_name_1602331 = "ภวังค์ที่เปล่งประกาย",
  str_pet_equip_name_1602341 = "อัสทรัมน็อกซ์",
  str_pet_equip_name_1502351 = "Edel Schwert",
  str_pet_equip_name_1602371 = "อาเรียในฝัน",
  str_pet_equip_name_1602381 = "เหรียญตราของคำสาบานนิรันดร์",
  str_pet_equip_intro_1200501 = "ค้างคาวดัดแปลงสองตัวนี้มีความยาวเท่ากับค้างคาวธรรมดา แต่ใบเลื่อยวงเดือนของพวกมันทำให้พลังทำลายล้างเพิ่มขึ้นอย่างมาก ไม่ว่าจะใช้เพื่อตัดเจาะหรือเหวี่ยงทำลายก็ตาม",
  str_pet_equip_intro_1300221 = "ริค เลื่อยไฟฟ้า เลื่องลือในการติดเครื่องเลื่อยไฟฟ้าและพุ่งเข้าโจมตีศัตรู กวัดแกว่งไม่เลือกหน้า\nไม่ว่าใครหรือสิ่งใดจะเข้ามาขวางทาง เมื่ออุณหภูมิของเลื่อยเพิ่มสูงขึ้น พลังของมันก็จะสูงขึ้นด้วย\nและริค เลื่อยไฟฟ้าจำเป็นต้องเติมน้ำมันดีเซลให้มันอย่างต่อเนื่อง พร้อมทั้งดื่มเองด้วยเช่นกัน\nเมื่อเลื่อยเริ่มร้อนจัด พลังโจมตีของริค เลื่อยไฟฟ้าจะพุ่งสูงลิ่ว",
  str_pet_equip_intro_1300461 = "ชุดไอเทมสี่ชิ้นของสี่สมาชิกประจำคณะคีตติง ตอนแรกพวกเขาไม่ค่อยสนใจไอเทมเหล่านี้มากนัก แต่ไม่นานก็พบว่าไอเทมสี่ชิ้นนี้มีความเชื่อมโยงกับคัมภีร์แห่งบทสวด ที่นอกจากเสริมพลังลูมินาติกส์ประเภทเสียงแล้ว ยังสร้างเอฟเฟกต์ที่ทรงพลังมากขึ้นเมื่อประสานงานกันอย่างลงตัวอีกด้วย",
  str_pet_equip_intro_1300471 = "ตอนที่โซยาเดินทางไปยังทะเลแห่งความตาย ควาร์เคียมที่นั่นมีผลกระทบปริศนากับเธอ และเธอก็ตกอยู่ในสภาวะหลับลึก หลังกลับมาจากทะเลแห่งความตาย โซยาได้รับส่วนหนึ่งของคริสตัลควาร์เคียมมา และได้เรียนรู้ที่จะใช้พลังของมัน เธอฝังคริสตัลนั้นลงบนคทาน้ำแข็งของตนเอง ซึ่งเพิ่มความแข็งแกร่งในการต่อสู้ขึ้นอย่างมาก",
  str_pet_equip_intro_1300491 = "ดาบคู่สีดำสนิทที่อีสต์วานซื้อให้เซลูซิดหลังจากที่เขาเข้าร่วมแก๊งอีสต์วาน ดาบน้ำหนักเบาสองเล่มนี้ว่ากันว่าเป็นเรลิกโบราณ และมีเกล็ดน้ำแข็งปกคลุมอยู่เสมอ หลังจากที่ได้มา ไม่นานเซลูซิดก็ช่ำชองศิลปะนักดวลดาบคู่",
  str_pet_equip_intro_1300511 = "เครื่องยิงระเบิดอุณหภูมิสูงและไรเฟิลสไนเปอร์ขนาดเล็กน้ำหนักเบา อาวุธคอมโบนี้มีแค่ซอร์คกับเบคค์เท่านั้นที่ใช้ ซอร์คใช้เครื่องยิงระเบิด ส่วนเบคค์ใช้ไรเฟิลสไนเปอร์ และทั้งสองก็ร่วมมือกันอย่างพร้อมเพรียงเพื่อปราบฝูงศัตรูอย่างง่ายดาย",
  str_pet_equip_intro_1300521 = "ขนนกที่พ่อแม่ทิ้งไว้ให้โดฟ สามารถเพิ่มความเร็วเคลื่อนที่ของโดฟได้อย่างมาก ทั้งยังเสริมพลังลูมินาติกส์ของเธอได้อีกด้วย ทำให้ขว้างดาบได้แม่นยำและว่องไวมากขึ้น",
  str_pet_equip_intro_1300531 = "ดาบของโจมู เก็บรักษาไว้ในกล่องสินค้า มีน้ำหนักเบาและง่ายต่อทั้งการใช้งานและพกพา หลังจากได้รับประสบการณ์หลายต่อหลายปี โจมูก็รู้ดีว่าจะใช้ดาบเล่มนี้อย่างไรเพื่อให้ความแข็งแกร่งของเขาถึงขีดสุดและมีพลังทำลายล้างในสมรภูมิ",
  str_pet_equip_intro_1300581 = "หลังจากได้เป็นอัศวิน ไม่นานเอมี่ก็ได้เป็นผู้ถือธงและได้รับหอกเล่มนี้ เธอสามารถฉีดลูมินาติกส์ของตัวเองให้กับหอกออโรรา ทำให้มันกลายเป็นธงที่สร้างความฮึกเหิมให้กับเพื่อนร่วมทีม และเพิ่มกำลังใจและการทำงานร่วมกันของพวกเขาได้",
  str_pet_equip_intro_1300591 = "ตอนที่เปปีใช้เปลวไฟของตนเป็นครั้งแรก เธอพลั้งมือและทำไฟลวกตัวเอง ขนนกทั้งหมดที่สูญเสียไปในวันนั้น มีแค่ชิ้นนี้ที่เหลือรอดมาได้ และยังคงมีร่องรอยของเปลวไฟริบหรี่อยู่ภายใน นับจากนั้นมาเปปีก็เก็บรักษาขนนกชิ้นนี้เอาไว้ และใช้พลังจากมันเพิ่มความว่องไวให้ตัวเอง",
  str_pet_equip_intro_1300741 = "ตอนที่ความสามารถของไวท์ดวาร์ฟระเบิดออก มีลูกแก้วสองลูกปรากฏขึ้นรอบตัวเขา ลูกแก้วเหล่านี้สามารถพุ่งเข้าโจมตีศัตรูที่อยู่ในระยะไกลได้ และหลอมรวมเข้าด้วยกันเพื่อสร้างการระเบิดขนาดใหญ่ที่สามารถกำจัดศัตรูใกล้เคียงทั้งหมดได้อีกด้วย",
  str_pet_equip_intro_1300801 = "ความหลงใหลในจักรกลของยูนิเมตกระตุ้นให้เธอสร้างแขนกลขึ้นมาอยู่เสมอ ว่ากันว่าสร้างมาแล้วไม่ต่ำกว่า 23 ชิ้น... เธอเก็บแขนกลเหล่านี้ไว้ในเป้ใบใหญ่ ซึ่งมักอัดแน่นไปด้วยอาวุธยุทโธปกรณ์ สามารถควบคุมแขนกลเหล่านี้ให้ต่อสู้และทำงานแทนตัวเธอได้ทุกเมื่อที่ต้องการ",
  str_pet_equip_intro_1300821 = "โอฟินาเกิดมาพร้อมกับหินเทอร์คอยซ์ เมื่อเติบโตขึ้น หินเทอร์คอยซ์นี้ก็สว่างขึ้นเรื่อย ๆ เช่นเดียวกับพลังของลูมินาที่อยู่ภายในหินที่เพิ่มขึ้นอย่างมาก เกิดเป็นความเชื่อมโยงปริศนากับเขาหยกขนาดใหญ่บนหัวของเธอ โอฟินานำเทอร์คอยซ์นี้ฝังลงบนคทาของตน และตอนนี้ก็นำมาใช้เพื่อนำทางลูมินาติกส์ภายในตัวเอง",
  str_pet_equip_intro_1300871 = "N/A",
  str_pet_equip_intro_1400071 = "ลูกดอกที่แหลมคมพิเศษนี้เป็นที่รู้จักกันในชื่อดาบเคียว หลังจากที่โคลเวอร์เข้าร่วมกับเรดีเซล เวรนช์ มันก็ได้รับการปรับปรุงเป็นพิเศษเพื่อให้เหมาะสมกับรูปร่างขนาดเล็กของเธอ โคลเวอร์อุทิศเวลานับไม่ถ้วนในการฝึกทักษะการใช้ดาบเคียวนี้ให้ชำนาญ และบัดนี้ก็เชี่ยวชาญอย่างมาก สามารถขว้างมันได้เร็วและไกลยิ่งกว่าเดิม",
  str_pet_equip_intro_1400081 = "หลังจากเข้าร่วมกับเรดีเซล เวรนช์ เจ้าจิ๋วไม่ได้รับอนุญาตให้ต่อสู้เนื่องจากอายุของเธอและเหตุผลอื่นอีกมากมาย จนกระทั่งเธอพบสปอตไลท์ในทะเลทรายเรดีเซลนั่นเอง เธอศึกษามันอย่างดีทุกครั้งที่มีเวลาว่างและดัดแปลงให้มันปล่อยลำแสงสุดเข้มข้นออกมา ซึ่งสามารถใช้โจมตีอิคลิพไซท์ได้",
  str_pet_equip_intro_1400161 = "คาฟกาบังเอิญไปเจออาวุธชิ้นนี้ขณะกำลังไล่ล่าอิคลิพไซท์ในซากโบราณปริศนากลางทะเลทรายเรดีเซล ไรเฟิลสไนเปอร์นี้เชื่อกันว่ามีต้นกำเนิดจากอารยธรรมโบราณ มีระบบติดตามด้วยแม่เหล็กไฟฟ้าเพื่อเพิ่มความแม่นยำ และสามารถยิงกระสุนเจาะทะลุอันทรงพลังได้",
  str_pet_equip_intro_1400171 = "โอดีปรับปรุงสว่านไฟฟ้าขนาดใหญ่เครื่องนี้ให้เป็นสีดำเงาสุดเท่ ผสมผสานด้วยประกายแสงสีแดง ถึงแม้จะมีขนาดใหญ่ไปบ้าง แต่น้ำหนักเบามาก และแรบบี้สามารถใช้งานได้อย่างง่ายดายในการต่อสู้ที่ดุเดือด ตอนนี้เธอใช้งานได้อย่างคล่องแคล่วแล้ว สว่านไฟฟ้าเครื่องนี้จึงกลายเป็นอาวุธชิ้นเดียวที่เธอใช้งาน",
  str_pet_equip_intro_1400321 = "แองเจิลเกิดมามีปีกที่สวยงามหนึ่งคู่ แต่ข้างหนึ่งเสียหายถาวรจากการโจมตีของอิคลิพไซท์ คงเหลือเพียงแค่กลุ่มขนนก แองเจิลพกพาขนนกที่เหลือนี้ติดตัว ด้วยหวังว่าวันหนึ่งจะสามารถซ่อมแซมปีกที่เสียหายของเธอได้",
  str_pet_equip_intro_1400351 = "นี่คือขนนกเส้นแรกที่งอกบนตัวเอโฮะหลังจากที่เธอเกิดมา และซุกซ่อนอยู่ท่ามกลางขนเส้นอื่นอีกจำนวนมากเมื่อเธอเติบโตขึ้น แต่หลังจากที่เอโฮะผ่านการผจญภัยมากมาย ลวดลายของขนเส้นนี้ก็เปลี่ยนแปลงไปอย่างน่าอัศจรรย์ ส่งผลให้เกิดเป็นรูปร่างแปลกตา กลายเป็นอาวุธที่โดดเด่นไม่ซ้ำใครของเอโฮะ",
  str_pet_equip_intro_1400401 = "โจแอนนี บูม หลงใหลเรื่องระเบิดเสมอมา หลังจากเข้าร่วมกับเรดีเซล เวรนช์\nความคลั่งไคล้นี้ก็ยิ่งจริงจังขึ้นกว่าเดิม ทุกครั้งที่ต่อสู้เธอจะใช้ระเบิดหลากหลายประเภท\nที่ตั้งใจทำขึ้นเองเพื่อระเบิดอิคลิพไซท์ให้กระจายด้วยแรงระเบิดที่ดุดันและเพลิงเขย่าขวัญ\nในความเห็นของเธอ โลกนี้ไม่มีอะไรวิเศษไปกว่าระเบิดดี ๆ สักลูก",
  str_pet_equip_intro_1400411 = "มิสบลังค์มีกระเป๋าเดินทางสีขาวติดตัวไปด้วยเสมอ ว่ากันว่าในนั้นมีอาวุธลึกลับจำนวนหนึ่ง บ้างก็ว่ามีบันทึกปากคำพยานจำนวนมากที่มิสบลังค์เก็บบันทึกเอาไว้ อย่างไรก็ดี ไม่มีใครเคยเห็นกระเป๋าใบนี้เปิดออกเลย",
  str_pet_equip_intro_1400441 = "นักวิจัยเมืองแกนน่อนใช้อิลลูมินาเทคและโลหะหายากในการสร้างอาวุธชิ้นล่าสุดขึ้นมาให้วิเวียนโดยเฉพาะ เป็นดาบคมกริบที่ทั้งเบาและบาง นอกจากนี้ยังเป็นตัวนำลูมินาในร่างกายของวิเวียน ซึ่งทำให้เพิ่มพลังได้อย่างมากอีกด้วย",
  str_pet_equip_intro_1400451 = "เลือดพิเศษที่ไหลเวียนอยู่ในร่างกายของเนลส์ทำให้เขามีความแข็งแกร่งอย่างมาก แต่ก็นำมาซึ่งความเจ็บปวดไม่สิ้นสุดเช่นกัน เพื่อที่จะข่มพลังจากเลือดของเขาไว้ เนลส์ใช้ค้อนศักดิ์สิทธิ์ทิ่มแทงตัวเอง แต่เมื่อเวลาผ่านไปไม่นาน ค้อนโชกเลือดนี้ก็กลับได้รับพลังปริศนาเช่นกัน ทำให้เนลส์สามารถปลดปล่อยความแข็งแกร่งของมันออกมาในการต่อสู้เพื่อทำลายศัตรูของเขา",
  str_pet_equip_intro_1400481 = "มีดคู่รูปงูที่คมกริบ เดย์นาใช้มาตั้งแต่ตอนที่เธอเริ่มเดินทางกับโรบิน และหลังจากต่อสู้มานานหลายปี เดย์นาก็ใช้งานได้อย่างช่ำชอง นอกจากเชือดเฉือนศัตรูของเธอได้อย่างรวดเร็วแล้ว มันยังปลดปล่อยลูมินาภายในร่างกายของเดย์นาเพื่อกำจัดคู่แข่งได้เร็วขึ้นอีกด้วย",
  str_pet_equip_intro_1400541 = "โคมไฟที่มีโซ่ยาวนี้คือสัญลักษณ์ของผู้คุ้มภัยยามราตรีและไม่เคยมอดดับ แม้แต่ในที่มืดมิด นาดีนผู้เป็นกัปตันผู้คุ้มภัยยามราตรีก็สามารถยกโคมไฟนี้ขึ้นสูง และใช้ลูมินาติกส์ของตนปล่อยแสงสว่างออกมา เพื่อขับไล่ทั้งความมืดและศัตรู",
  str_pet_equip_intro_1400571 = "แม้จะดูเหมือนไม้ค้ำเดิน แท้จริงแล้วมันทำจากอิลลูมินาเทคใหม่ล่าสุด สามารถเปลี่ยนรูปร่างเป็นมีด ทั้งยังใช้รักษาและกำจัดอารมณ์ที่ไม่คงที่ในหัวใจของฟิลิชีได้อีกด้วย",
  str_pet_equip_intro_1400611 = "หลังจากค้นพบความแข็งแกร่งที่แท้จริงของแชนดรา กรอนรูก็ทำแหวนให้เธอวงหนึ่ง แหวนวงนี้ทำให้แชนดราสามารถแปลงอารมณ์ด้านลบที่เธอดูดซับและปล่อยเปลวเพลิงที่วิจิตรงดงามได้ จึงถือว่าเป็นผลิตภัณฑ์อิลลูมินาเทคที่ล้ำหน้าที่สุดชิ้นหนึ่ง",
  str_pet_equip_intro_1400681 = "ตอนที่เวนดี้ออกไปส่งของ เธอประสบกับพายุเฮอร์ริเคนที่ไม่ค่อยพบเห็นได้ในทะเลทราย ขณะคิดว่าจะต้องจบชีวิตลงแน่แล้ว ก็มีขนนกลอยมาตกบนใบหน้า ทันใดนั้นเวนดี้ก็เกิดมีแรงฮึดมหาศาลขึ้นมาและบินออกจากพายุเฮอร์ริเคน จากวันนั้นเป็นต้นมา เธอก็เก็บขนนกชิ้นนี้ไว้กับตัวตลอดเวลา นอกจากเป็นเครื่องเตือนใจถึงความแข็งแกร่งของตนแล้ว มันยังมอบความกล้าหาญให้อีกด้วย",
  str_pet_equip_intro_1400731 = "ตรีศูลนี้เป็นของทั้งสองคู่หู แต่คนที่ใช้งานมักเป็นแพตซี่ เพราะมีพรสวรรค์ในการควบคุมมัน เมื่อแพตตี้นำมาใช้ เธอใช้แทงศัตรูเพียงอย่างเดียว แต่ถึงจะจัดการกับคู่แข่งได้อย่างรวดเร็ว มันก็ทำอันตรายพวกพ้องของเธอได้เช่นกัน และจะต้องใช้ด้วยความระมัดระวัง",
  str_pet_equip_intro_1400791 = "ตราชูแห่งการพิพากษาคือมรดกของครอบครัวมิเชนนีที่สามารถย้อนรอยไปถึงช่วงการก่อตั้งลูโมโพลิส นี่คือไอเทมที่รับพลังงานจากศรัทธาของผู้ใช้งาน และมีความสามารถในการตัดสินศัตรูของมัน โดยเปลี่ยนคำพูดเป็นการโจมตีด้านจิตใจ",
  str_pet_equip_intro_1400811 = "บุคลากรฝ่ายเทคโนโลยีของเรดีเซล เวรนช์ได้ปรับปรุงอุปกรณ์ต่อยมวยของบร็อคให้เป็นพิเศษ โดยเสริมความแข็งแกร่งเพื่อใช้งานหนักแบบสุดเหวี่ยง อุปกรณ์นี้สามารถใช้กังหันของบร็อคเพื่อเพิ่มผลกระทบจากแรงดูดและการฉีดยาโดยไม่ใช้เข็ม ทำให้บร็อคผลักคู่แข่งให้กระเด็นได้อย่างง่ายดาย",
  str_pet_equip_intro_1400831 = "ไม้กวาดสีขาวที่มีรูปแบบกลไกไม่เหมือนใคร พัฒนาโดยห้องปฏิบัติการวิจัยทางวิทยาศาสตร์ของสหพันธรัฐอิลลูมินาโดยเฉพาะ ประกอบด้วยอุปกรณ์ส่งกำลังเครื่องกลที่ซับซ้อน โดยทำงานร่วมกับลูมินาติกส์พิเศษของลิลเลียมเพื่อกวาดขยะทุกชนิด รวมถึงกวาดล้างสัตว์รบกวนทุกรูปแบบในการต่อสู้",
  str_pet_equip_intro_1400851 = "กระเป๋าเดินทางของเจนนั้นเต็มไปด้วยแฟ้มเอกสารและข้อมูลทุกประเภท เช่นความลับของอัมบราตัน ความขัดแย้งระหว่างแก๊งชื่อดัง ข้อตกลงลับที่ร่างขึ้นโดยกลุ่มคนที่ดำรงตำแหน่งสูงสุดของประเทศ และอื่น ๆ เจนเป็นคนบอกเองว่านี่คือแหล่งที่มาของความแข็งแกร่งของเธอ",
  str_pet_equip_intro_1400861 = "ว่ากันว่าดาบพิธีกรรมเล่มนี้ทำขึ้นตามแบบที่ยูริอาห์วาดด้วยตัวเอง เป็นที่รู้จักในชื่อดอกไม้แห่งภาวนา แม้จะมีความทนทานอย่างมาก แต่ใบมีดกลับบางเกินไป และไม่สามารถต่อกรกับอาวุธส่วนมากได้ ความจริงก็คือ มีเพียงยูริอาห์เท่านั้นที่สำแดงอานุภาพสูงสุดของมันได้โดยใช้เทคนิคลับของเธอเอง",
  str_pet_equip_intro_1400911 = "นี่คือฮาร์ปของพ่อของโคลอี้ เธอสามารถเล่นได้อย่างชำนาญ และถักทอลูมินาติกส์ของเธอเองให้เป็นโน้ตต่าง ๆ เพื่อใช้ลูมินาติกส์ของเธอชักนำคนอื่นและปลอบประโลมสหายที่บาดเจ็บ",
  str_pet_equip_intro_1500091 = "กล่องที่วิกตอเรียมอบให้หลังจากเข้าร่วมทรู ออเดอร์ ข้างในมีสัตว์บางอย่างที่กลืนกินได้ทุกสรรพสิ่ง ไม่มีผู้ใดล่วงรู้จุดประสงค์ของมันอย่างชัดเจน และรู้เพียงว่ามันชอบความทรงจำที่เจ็บปวดเป็นพิเศษ หลังจากที่เฟาสต์ได้รับกล่องใบนี้มา เขาก็ไม่ถูกฝันร้ายตามหลอกหลอนอีกต่อไป",
  str_pet_equip_intro_1500121 = "อาวุธที่ฝ่ายการวิจัยทางวิทยาศาสตร์ของสหพันธรัฐอิลลูมินาทำให้เนเมซิสโดยเฉพาะ มีความสามารถในการเหนี่ยวนำกระแสไฟฟ้าสูง โดยการควบคุมกระแสไฟเพื่อสตันหรือทำให้ศัตรูบาดเจ็บ มันช่วยให้เนเมซิสมีความสามารถที่อเนกประสงค์ในหลากหลายสถานการณ์",
  str_pet_equip_intro_1500131 = "คริสตัลน้ำแข็งชิ้นแรกที่โนอาห์ทำขึ้นโดยใช้ลูมินาติกส์ของตนเอง มันมีรูปร่างที่พิเศษมาก แม้กระทั่งหลังจากที่ได้เรียนรู้ทักษะในการทำคริสตัลน้ำแข็งขั้นสูงยิ่งขึ้น เธอก็ยังเก็บชิ้นงานสุดพิเศษนี้ไว้เป็นที่ระลึก ในการผจญภัยครั้งหนึ่ง เธอพบว่าคริสตัลน้ำแข็งนี้ได้เปลี่ยนแปลงไป โดยให้พลังแห่ง \"ความหวัง\" เพื่อเพิ่มประสิทธิภาพการต่อสู้ของโนอาห์ขึ้นอย่างมาก",
  str_pet_equip_intro_1500181 = "สมาชิกเรดีเซล เวรนช์ค้นพบกีตาร์ไฟฟ้านี้ฝังลึกอยู่กลางทะเลทราย ตอนแรกก็ทิ้งไว้บนรถบรรทุก แต่หลังจากที่เรจินาเข้าร่วมกับเรดีเซล เวรนช์ ไม่นานเธอก็พบว่ากีตาร์ไฟฟ้าตัวนี้ตรงกับแนวดนตรีของเธออย่างสมบูรณ์แบบ ทำให้ได้ปลดปล่อยความแข็งแกร่งในตัวเองออกมา",
  str_pet_equip_intro_1500201 = "หอกเล่มนี้คาร์ลีนได้รับมาจากผู้เป็นพ่อ ซึ่งก็คือดยุกซอร์ลา ในวันที่เธอได้เป็นอัศวิน หลังจากการต่อสู้นับครั้งไม่ถ้วนอย่างเต็มความสามารถ สัญลักษณ์พิเศษของคาร์ลีนก็ปรากฏอยู่บนหอกเล่มนี้ เมื่อรวมเข้ากับวัตถุดิบชั้นเลิศบางชนิด หอกของคาร์ลีนจะทรงพลังอย่างยิ่ง",
  str_pet_equip_intro_1500211 = "กรรไกรที่สหพันธรัฐอิลลูมินาทำให้โจลาเป็นพิเศษ ปรับขนาดได้ ตอนแรกโจลาใช้เป็นเครื่องมือทำสวนเพื่อช่วยเก็บเกี่ยวพืชผล แต่ไม่นานเธอก็เพิ่มลูกเล่นใหม่ให้มันเพื่อรับบทบาทสำคัญในการต่อสู้",
  str_pet_equip_intro_1500311 = "หอกเล่มนี้คาร์ลีนได้รับมาจากผู้เป็นพ่อ ซึ่งก็คือดยุกซอร์ลา ในวันที่เธอได้เป็นอัศวิน หลังจากการต่อสู้นับครั้งไม่ถ้วนอย่างเต็มความสามารถ สัญลักษณ์พิเศษของคาร์ลีนก็ปรากฏอยู่บนหอกเล่มนี้ เมื่อรวมเข้ากับวัตถุดิบชั้นเลิศบางชนิด หอกของคาร์ลีนจะทรงพลังอย่างยิ่ง",
  str_pet_equip_intro_1500331 = "ธนูยาวที่ห้องปฏิบัติการวิจัยทางวิทยาศาสตร์เมืองแกนน่อนทำให้ไวซ์เป็นพิเศษ เช่นเดียวกับเกราะของมังกร มันเสริมความแข็งแกร่งด้วยวัสดุพิเศษ ที่นอกจากเพิ่มความแม่นยำให้กับลูมินาติกส์ของไวซ์แล้ว ยังเพิ่มพลังอย่างมากอีกด้วย",
  str_pet_equip_intro_1500341 = "หอกเล่มนี้คาร์ลีนได้รับมาจากผู้เป็นพ่อ ซึ่งก็คือดยุกซอร์ลา ในวันที่เธอได้เป็นอัศวิน หลังจากการต่อสู้นับครั้งไม่ถ้วนอย่างเต็มความสามารถ สัญลักษณ์พิเศษของคาร์ลีนก็ปรากฏอยู่บนหอกเล่มนี้ เมื่อรวมเข้ากับวัตถุดิบชั้นเลิศบางชนิด หอกของคาร์ลีนจะทรงพลังอย่างยิ่ง",
  str_pet_equip_intro_1500361 = "ไฮแดรดพบวัตถุชิ้นนี้ในซากโบราณและไม่นานก็ค้นพบว่ามันมีพลังโบราณที่ลึกลับ มันดูเหมือนขวดแก้วที่ส่องแสงสีฟ้าสวยงาม และสามารถปลดปล่อยเวทมนตร์พิเศษเพื่อเรียกสัตว์ที่เรียกว่า \"หมาป่าเงา\" มาช่วยไฮแดรดในการต่อสู้",
  str_pet_equip_intro_1500421 = "มีดบาร์ตันเป็นอาวุธหลักรุ่นปรับปรุงของดาบปลายแหลมที่ทำขึ้นจากวัสดุหายาก และสามารถนำทางลูมินาเพื่อสร้างดาเมจถึงตายได้ ปืนอัตโนมัติรุ่น \"แต่งโดยเชอร์แมน\" คือรุ่นปรับปรุงของปืนอัตโนมัติเชอร์แมนแบบมาตรฐาน โดยบรรจุกระสุนได้สองเท่า มีลำกล้องที่หนักขึ้น และเพิ่มพลังการยิงได้อย่างมาก",
  str_pet_equip_intro_1500701 = "แหวนทองคำสลักข้อความปริศนา สามารถนำทางพลังอันแกร่งกล้าภายในเลือดของลีโอนาและนำพลังอันบริสุทธิ์ของเปลวไฟที่เรียกว่า \"ลมหายใจมังกร\" มาใช้เพื่อทำลายทุกอย่างในสายตา",
  str_pet_equip_intro_1500751 = "โอดีใช้ความรู้ที่ได้รับในสหพันธรัฐอิลลูมินาและแรงบันดาลใจอัจฉริยะของเธอในการเลือกวัสดุที่มีประโยชน์จำนวนหนึ่งจากคลังเก็บของปล้นสะดมเรดีเซล เวรนช์ และค่อย ๆ ทำสายเคเบิลใยแก้วที่สมบูรณ์แบบขึ้นมา นี่เป็นอาวุธแปลกประหลาดที่ทำงานได้เองด้วยพลังงานจากใบพัดที่เคลื่อนที่เหมือนหนอนทราย",
  str_pet_equip_intro_1500761 = "ดูเหมือนว่าครั้งหนึ่งเคยเป็นอาวุธของมอนสเตอร์บางอย่างในทะเล แม้ว่าเคลเคนจะอ้างว่าเขาสร้างหนวดนี้ขึ้นมาโดยใช้ลูมินาติกส์พิเศษของตนเอง ก็ไม่มีผู้ใดรู้ที่มาที่แท้จริงของมัน",
  str_pet_equip_intro_1500781 = "แม้ว่ามันจะเป็นแค่ท่อเหล็กธรรมดา แต่ก็สามารถเป็นอาวุธมรณะได้เมื่ออยู่ในมือของผู้ที่คู่ควร โรบินสามารถใช้ลูมินาติกส์ของเธอเองเพื่อสร้างกระแสลมเชือดเฉือนที่คมกริบได้ด้วยท่อนี้ ซึ่งสามารถตัดเกราะของศัตรูได้ด้วยพลังที่น่ากลัวของมัน",
  str_pet_equip_intro_1500841 = "คทาทองคำบริสุทธิ์ของอสรพิษคู่แฝดที่ออกแบบพิเศษให้มีเปลวไฟวนเวียนอยู่ภายใน อีสต์วานสามารถใช้คทานี้เรียกเปลวไฟแฟนท่อมสีน้ำเงินมาแผดเผาทุกสิ่งในบริเวณใกล้ตัวเขาได้ พลังงานที่ปลดปล่อยออกมาจากเปลวไฟนี้นอกจากกำจัดคู่แข่งได้แล้ว ยังเพิ่มความแข็งแกร่งในการต่อสู้ให้กับทีมของเขาอีกด้วย",
  str_pet_equip_intro_1500881 = "ถุงหนังใส่ระเบิดนี้เต็มไปด้วยระเบิดนานาชนิดที่ผลิตขึ้นในปริมาณมาก โดยปกติแล้วระเบิดพวกนี้ไม่ได้รุนแรงอะไรมากนัก แต่แม็กกี้ได้ฉีดลูมินาปริมาณมากเข้าไป มันจึงสร้างแรงระเบิดหายนะได้",
  str_pet_equip_intro_1500901 = "เลื่อยวงเดือนไฟฟ้ารุ่นปรับปรุงที่มีสายสะพายพิเศษ ลือกันว่าตอนแรกมันคือไมโครโฟน และบาร์บาร่าขอให้นำมาทำเป็นอาวุธเพื่อจัดการแฟน ๆ ที่บ้าคลั่งของเธอ... แต่บาร์บาร่าปฏิเสธเสียงแข็งในเรื่องนี้",
  str_pet_equip_intro_1500921 = "แพกต์ไม่ได้ตั้งใจจะพกพาวัตถุรูปวงล้อที่ปกคลุมด้วยหนามเหี่ยวเฉาชิ้นนี้ ไม่ว่าจะโยนไปที่ไหนมันก็ดูเหมือนผีที่ไม่ยอมไปเกิดใหม่ ไม่ว่าเธอจะหนีไปไกลแค่ไหน ในที่สุดมันก็กลับไปหาเธอได้อยู่ดี แม้จะลึกลับและน่ากลัว แต่มันก็ให้พลังที่ยิ่งใหญ่กับเธอ",
  str_pet_equip_intro_1600011 = "กระจกบานใหญ่นี้เป็นเรลิกของนอร์ธแลนด์ ซึ่งสามารถสร้างภาพลวงปริศนาได้ เรียกกันว่า \"กระจกนอร์ธแลนด์\" มันเป็นของที่นิคินิสขาดไม่ได้ นอกจากจะใช้ลูมินาติกส์ทำให้กระจกบานนี้ลอยได้แล้ว เธอยังทำให้ลูมินาไหลผ่านกระจกและดอกไม้ของตนเพื่อทำลายคู่แข่งในการต่อสู้ได้อีกด้วย",
  str_pet_equip_intro_1600021 = "ดาบนี้มาจากแดนตะวันออกไกลเช่นเดียวกับฮิอิโระ ลือกันว่าซาคาเอะ ชิเงโอะ อาจารย์ของฮิอิโระ ได้มอบพลังมหาศาลให้กับดาบเล่มนี้และได้มอบพลังแห่งชีวิตของเขาให้กับมัน โดยปรับแต่งให้เข้ากับแก่นของฮิอิโระเอง ดังนั้นอาวุธชิ้นนี้จึงเรียกว่า \"ดาบคาตานะ: ซาคาเอะ\" มันเป็นอาวุธที่ทรงพลังอย่างยิ่ง แต่ถ้าใช้เป็นเวลานาน มันจะดูดพลังในตัวของฮิอิโระ",
  str_pet_equip_intro_1600031 = "หอกเล่มนี้คาร์ลีนได้รับมาจากผู้เป็นพ่อ ซึ่งก็คือดยุกซอร์ลา ในวันที่เธอได้เป็นอัศวิน หลังจากการต่อสู้นับครั้งไม่ถ้วนอย่างเต็มความสามารถ สัญลักษณ์พิเศษของคาร์ลีนก็ปรากฏอยู่บนหอกเล่มนี้ เมื่อรวมเข้ากับวัตถุดิบชั้นเลิศบางชนิด หอกของคาร์ลีนจะทรงพลังอย่างยิ่ง",
  str_pet_equip_intro_1600041 = "แม้ว่าไม้เบสบอลลวดหนามของคุมะและจรวดสีส้มของเพนจี้จะดูน่ากลัว แต่คุมะกับเพนจี้ก็ไม่ได้พึ่งพาสิ่งเหล่านี้เป็นหลักในการโจมตี พวกเขาใช้ลูมินาติกส์อันทรงพลังและร่วมมือกันอย่างเหนียวแน่นเพื่อเอาชนะศัตรูในการต่อสู้แทน",
  str_pet_equip_intro_1600051 = "หลังจากที่มีอาย้ายมาอยู่ไม่ไกลจากอัมบราตัน บุคลิก \"บาบายาก้า\" ของเธอก็สร้างปัญหาในเมืองขึ้นบ่อยครั้ง จนเริ่มลือกันหนาหูว่ามี \"แมงมุมดำ\" ชั่วร้ายอยู่ในเมือง หลังจากที่ได้ยินเรื่องนี้ บาบายาก้าก็ทำเครื่องประดับนี้ขึ้นมาโดยใช้ลูมินาติกส์ของตนเพื่อเพิ่มพลังของตนกับมีอา",
  str_pet_equip_intro_1600061 = "หอกเล่มนี้คาร์ลีนได้รับมาจากผู้เป็นพ่อ ซึ่งก็คือเจ้าเมืองชวาตส์นั่นเอง ในวันที่เธอได้เป็นอัศวิน หลังจากการต่อสู้นับครั้งไม่ถ้วนอย่างเต็มความสามารถ สัญลักษณ์พิเศษของคาร์ลีนก็ปรากฏอยู่บนหอกเล่มนี้ เพื่อเป็นสัญลักษณ์แสดงถึงความชำนาญขั้นสูงสุดในการใช้อาวุธชนิดนี้ ทั้งยังเพิ่มพลังหอกของเธอขึ้นอย่างมากอีกด้วย",
  str_pet_equip_intro_1600101 = "\"เวทมนตร์ฉบับกระเป๋า\" ของลูอิสสร้างสิ่งต่าง ๆ ได้ทุกชนิด แต่ที่สุดแล้วสิ่งเหล่านั้นก็หายไป เหลือแต่เพียงหนังสือเทพนิยายเล่มนี้ในวันนี้ เธอเชื่อว่ามันมีพลังเวทมนตร์จึงพกติดตัวเอาไว้ และแน่นอนว่ามันเริ่มเสริมพลังภายในตัวเธอแล้วจริง ๆ",
  str_pet_equip_intro_1600111 = "ดาบคาตานะเล่มนี้เป็นมรดกครอบครัวคาร์ติมาของชาโรนา ว่ากันว่าตกทอดมาจากตะวันออกไกลนานนับพันปีแล้ว ใบมีดของมันมีออร่าสีน้ำเงินเหมือนเปลวไฟแผ่ออกมาตลอดเวลา และทำงานเข้ากันได้อย่างสมบูรณ์แบบกับพลังแห่งมังกรของชาโรนาเพื่อสร้างพลังทำลายล้างที่น่ากลัว",
  str_pet_equip_intro_1600141 = "มรดกของครอบครัวชวาตส์ ดาบใหญ่เล่มนี้เรียกกันว่าดาบแห่งราชัน มันดูเหมือนสัญลักษณ์แห่งอำนาจมากกว่าจะเป็นอาวุธจริง ๆ เวลาที่ชวาตส์นำมาใช้ มันจะเรียกดาบแสงมารอบตัวชวาตส์เหมือนกลุ่มดาวที่เปล่งประกายและทำตามคำสั่งของเขา",
  str_pet_equip_intro_1600191 = "ตำราสีดำของวิกตอเรีย ว่ากันว่าเดิมทีมันเคยเป็นตำราเวทมนตร์ โดยปกติแล้วในหน้าหนังสือจะว่างเปล่า และไม่สามารถเขียนอะไรลงไปได้ ตำนานกล่าวว่าเมื่อถึงเวลาแห่งการรู้แจ้ง หมึกสีแดงสดจะปรากฏขึ้นในหน้ากระดาษทั้งเล่ม และคงเหลือไว้ซึ่งคำพยากรณ์เมื่อสีของมันจางลง",
  str_pet_equip_intro_1600231 = "คลาริเนตนี้เป็นของที่พ่อแม่ทิ้งไว้ให้คอนนอลลี เธอใช้ช่วงชีวิตที่เดียวดายในวัยเด็กฝึกเล่นคลาริเนตนี้และในที่สุดก็ได้ปลุกพลังที่ซุกซ่อนอยู่ในตัวขึ้นมา มอนสเตอร์มีหนวดปรากฏขึ้นจากคลาริเน็ตนี้ เรียกว่าแอนตัน แอนตันจะพากันทำตามคำสั่งของคอนนอลลีทุกอย่าง ไม่ว่าจะให้โจมตีหรือรัดรึงศัตรู",
  str_pet_equip_intro_1600251 = "แม้ว่าปืนพกที่ปรากฏในรถไฟยมโลกของคารอนจะดูเหมือนปืนไฟธรรมดา แต่หลังจากที่คารอนปลดปล่อยความสามารถของเขาออกมา ปืนพกกระบอกนี้ก็เกิดความเชื่อมโยงลึกลับกับตัวเขา และพลังของมันก็เพิ่มขึ้นอย่างมหาศาล",
  str_pet_equip_intro_1600261 = "วงแหวนอัคคีทองคำที่ล้อมรอบอูริเอลเต็มไปด้วยช่องว่างที่สามารถพ่น เก็บกัก และดูดซับเปลวไฟได้ วงแหวนนี้ทำขึ้นเพื่ออูริเอลเป็นพิเศษ ไอเทมนี้สามารถรับพลังเปลวไฟสุดพิเศษของเธอได้เท่านั้น",
  str_pet_equip_intro_1600271 = "โดรนดาบวงแหวนที่มีใบมีดคมกริบ ทำขึ้นเป็นพิเศษในลูโมโพลิสเพื่อมอบให้กับมิคาเอล และมิคาเอลได้สลักรูนเวทมนตร์เอาไว้ มันสามารถนำทางพลังสายฟ้าในร่างกายของมิคาเอลเพื่อทิ่มแทงรวดเร็วปานสายฟ้าได้",
  str_pet_equip_intro_1600281 = "กล่องกลไกขนาดใหญ่ที่มีรูปร่างแบบไม้กางเขน ภายในมีกระสุนน้ำมนต์จำนวนมาก ราฟาเอลสามารถควบคุมน้ำมนต์ข้างในเพื่อทำดาเมจให้กับศัตรูและรักษาพันธมิตรได้",
  str_pet_equip_intro_1600291 = "ลูกคริสตัลสีเหลืองอ่อนที่มีลวดลายธรรมดา ลูกคริสตัลนี้เพิ่มพลังลูมินาติกส์ของกาบริเอลได้ และทำให้เธอสามารถเรียกกรงนกมาใช้งานได้ทุกที่ทุกเวลา",
  str_pet_equip_intro_1600381 = "เครื่องจักรโบราณที่เรียกกันว่า \"โทรน\" นี้ ที่จริงแล้วคือพาหนะส่วนตัวของกรอนรู โครงสร้างที่เหมือนป้อมปราการนี้มีพลังทำลายล้างมหาศาล มันถูกควบคุมโดยถุงมือจักรกลโทรน และกรอนรูสามารถทำให้มันเคลื่อนที่ได้ตามการเคลื่อนไหวของเธอ",
  str_pet_equip_intro_1600601 = "ปืนดัดแปลงสามกระบอกนี้มีรูปร่างแปลกและแตกต่างจากปืนพกมาก ด้วยมือจักรกลของเธอและแมกกาซีน 6 นัด โจนาสามารถยิงห่ากระสุนเข้าใส่ศัตรูเพื่อเป็นการสกัดกั้นที่ทรงพลังได้",
  str_pet_equip_intro_1600641 = "วราธ ผู้บัญชาการที่ชำนาญ ได้สั่งการให้ห้องปฏิบัติการวิจัยทางวิทยาศาสตร์ของสหพันธรัฐอิลลูมินาปรับปรุงเครื่องจักรลอยตัวที่ทำจากโลหะแข็งมาก ซึ่งตอนนี้เรียกว่า \"อาร์เรย์ลาดตระเวน\" เธอจึงเพิ่มการควบคุมอาร์เรย์ลาดตระเวนด้วยถุงมือต่อยมวย \"เอซ\" ทำให้เธอสามารถควบคุมมันได้อย่างง่ายดาย",
  str_pet_equip_intro_1600771 = "ดาบยาวนี้เรียกว่า \"ดาบดาวโคจร\" ด้ามดาบล้อมรอบด้วยวงโคจรเป็นรูปกากบาท ซึ่งเป็นสัญลักษณ์ของอำนาจราชินีแห่งทิศเหนือ แม้ว่าจะทำด้วยพลังออโรราที่บริสุทธิ์ แต่เบธเลเฮมไม่ค่อยใช้ในการต่อสู้ และบางคนเชื่อว่ามันเป็นสัญลักษณ์ของตัวตนของเธอมากขึ้น",
  str_pet_equip_intro_1600891 = "นี่คือชื่อที่เรียกรวมของ \"คทาแห่งการตัดสิน\" และ \"ดาบแห่งการหยิบยืม\" ที่อิริดอนเป็นผู้กวัดแกว่ง คทาแห่งการตัดสินเป็นตัวแทนวงศ์ตระกูลของอิริดอน ส่วนดาบแห่งการหยิบยืมเป็นตัวแทนของความปรารถนาที่แท้จริงในหัวใจของเธอ",
  str_pet_equip_intro_1500871 = "หลังจากที่ได้รับตำแหน่งที่ตกทอดมาด้วยความชอบธรรม เบเวอร์ลีก็ทำเข็มกลัดรูปหอกนี้ขึ้นมา ผนวกกับความสามารถของลูมินาในการสร้างสายฟ้า ทำให้เบเวอร์ลีสามารถสร้างหอกสายฟ้าเพิ่มได้โดยมีความว่องไวและรุนแรงยิ่งกว่าเดิม",
  str_pet_equip_intro_1500241 = "ปืนคู่ลุกโชนคืออาวุธปืนที่เบนนี่ใช้เพื่อยิงคุ้มกัน ว่ากันว่าสามารถปรับแต่งเพื่อวัตถุประสงค์ต่าง ๆ ได้หลากหลาย ดาบความเร็วแสงคือดาบที่คมกริบอย่างยิ่งของคุโระ อาวุธสองชิ้นนี้ทำให้เบนนี่และคุโระไม่มีผู้ใดเอาชนะได้",
  str_pet_equip_intro_1401011 = "หลังจากที่แอนเซียเข้าร่วมกับกองทัพ เธอก็ได้ทำให้พลังคลื่นเสียงของตนกลายเป็นที่รู้จัก เพื่อให้ห้องทดลองเทคโนโลยีในแกนน่อนทำเครื่องพ่นไอน้ำนี้ให้ตนโดยเฉพาะ เรื่องราวเล่าว่าแอนเซียใช้มันเพื่อสร้างคลื่นเสียงในการต่อสู้",
  str_pet_equip_intro_1600931 = "ดาบโค้งบัญชาเล่มนี้ นอกจากใช้เพื่อออกคำสั่งและฝึกฝนกองทหารแล้ว ยังมีลูมินาสุดพิเศษของมิการ์ดอยู่ภายในอีกด้วย จึงสามารถปล่อยแสงน่ากลัวออกมา ซึ่งสามารถทำให้ข้าศึกที่สัมผัสละลายได้",
  str_pet_equip_intro_1401021 = "เพื่อควบคุมระเบิดพลาสมาที่กระจัดกระจาย เทสซาได้ซื้อถุงมือบุฉนวนคู่นี้มา โดยสั่งทำพิเศษจากกิลด์ในอัมบราตัน ถึงกับปักตราประจำตัวของตนไว้ด้วย ด้วยถุงมือบุฉนวนคู่นี้ เทสซาจึงควบคุมพลังงานพลาสมาของตนได้ง่ายขึ้น",
  str_pet_equip_intro_1500991 = "ดาบวิเศษของครอบครัวของอาเรียซึ่งมีคำสาปที่ทรงพลัง มีแสงสีดำที่บ่งบอกถึงลางร้าย สามารถรวบรวมลูมินาสำหรับการฟาดฟันที่แข็งแกร่งได้ และทำให้อาเรียควบคุมหนามดำให้โจมตีศัตรูและป้องกันพันธมิตรได้ด้วย",
  str_pet_equip_intro_1600961 = "วงน้ำพิเศษที่ซาริเอลสร้างขึ้นด้วยพลังสูงสุด ดูเหมือนน้ำพุ่งกระจาย แต่จริงๆ แล้วมีความแข็งมาก ซาริเอลเชื่อว่ารูปร่างและสีสันน่าอัศจรรย์นี้แสดงถึงความสามารถของเธอ: \"วงน้ำสองสี\" และ \"น้ำวนอันมืดมิด\" มันช่วยเสริมพลังความสามารถทั้งสองอย่าง",
  str_pet_equip_intro_1500971 = "ประสบการณ์งานศัลยกรรมของโคแร็กซ์ทำให้เขาไม่เป็นสองรองใครเมื่อมีมีดผ่าตัดอยู่ในมือ สำหรับโคแร็กซ์แล้ว ไม่ว่าจุดไหนในร่างกายของศัตรูก็เป็นจุดอ่อนและเป็นเป้าหมายของการชำแหละทั้งนั้น มีดผ่าตัดเหล่านี้นอกจากคมกริบด้วยพลังลูมินา ยังควบคุมการโจมตีจากระยะไกลได้อีกด้วย",
  str_pet_equip_intro_1500981 = "ดอกไม้สีดำนี้อยู่กับคุสคูตามาตั้งแต่เกิด แต่เมื่อพลังของเธอแสดงออกมามันกลับเหี่ยวแห้งไป ในที่สุดคุสคูตาก็ค้นพบว่ามันเชื่อมโยงกับพลังของตนและเริ่มนำมาสวมใส่ไว้ตลอดเวลา",
  str_pet_equip_intro_1400621 = "ตอนที่ซิลวาเริ่มหัดฟันดาบ พ่อได้มอบเถาวัลย์ให้อันหนึ่งและสอนให้เขาเปลี่ยนมันเป็นดาบด้วยพลังของตนเอง ซิลวาเก็บเถาวัลย์นี้ไว้ตั้งแต่นั้นเป็นต้นมาเพื่อเป็นที่ระลึกถึงพ่อ",
  str_pet_equip_intro_1300941 = "มรดกจากพ่อแม่ของลีอาห์ มันทำให้ลีอาห์สามารถโจมตีได้ด้วยพลังแห่งธรรมชาติ รวมเอาไอน้ำในป่ามาห่อหุ้มตัวเธอเองและเพื่อนร่วมทีมเพื่อเพิ่มการป้องกัน",
  str_pet_equip_intro_1601031 = "หลังจากค้นพบพลังหายนะที่เอาชนะได้ยากในดวงตาข้างขวาของเอซี่ ทรู ออเดอร์ได้สร้างคทานี้ให้และสลักตราประจำตัวของเธอ ทำให้เธอควบคุมพลังของตนเองได้โดยอาศัยการเพ่งพลังเวท",
  str_pet_equip_intro_1501001 = "กุญแจสำหรับเปิดสุสานแห่งดวงดารา เมื่อมีกุญแจนี้ ซิคาเรสามารถเสกกับดักและมอนสเตอร์นับไม่ถ้วนในจุดที่ศัตรูยืนกันอยู่ รวมถึงเสกสุสานแห่งดวงดาราของจริงขึ้นมาใต้เท้าของเธอเองเพื่อมอบพลังที่ยิ่งใหญ่กว่าเดิมให้ตนเอง",
  str_pet_equip_intro_1400951 = "เลสเตอร์เกิดมามีกลิ่นตัวที่แรงมาก แต่ไม่ได้กัดกร่อนความมั่นใจในตัวเอง กลับเป็นแรงผลักดันให้เธอทำชุดพิเศษขึ้นมาเพื่อเก็บกักกลิ่นกายไว้ในถังก๊าซที่เธอใช้ขว้างใส่ทำร้ายศัตรู",
  str_pet_equip_intro_1500561 = "คอนสแตนตินเก็บปืนกระบอกนี้ได้จากซากโบราณในการเดินทางของเขา เจ้าของเดิมของมันต่อสู้กับอิคลิพไซท์จนตัวตาย คอนสแตนตินชื่นชมความมุ่งมั่นและนำอาวุธปืนนี้มาเป็นอาวุธประจำตัว",
  str_pet_equip_intro_1400671 = "เดิมทีกระดุมคอนี้สลักจากคริสตัลธรรมดา และกลายเป็นทับทิมล้ำค่าที่ให้ความอบอุ่นอย่างน่าอัศจรรย์เมื่ออลิซแสดงพลังของเธอออกมาเป็นครั้งแรก",
  str_pet_equip_intro_1600301 = "ว่ากันว่าหัวหน้าเรดีเซล เวรนช์คนแรกเป็นผู้ใช้ประแจยักษ์นี้ และมีเพียงผู้ที่นำมันมาใช้งานได้อย่างง่ายดายเท่านั้นที่มีคุณสมบัติที่จะเป็นหัวหน้า หัวค้อนแข็ง ๆ ประกอบกับพลังของซินซาทำให้มันทุบทำลายได้ทุกอย่าง",
  str_pet_equip_intro_1601051 = "หลังจากการพักฟื้นของอีฟ บุคลากรฝ่ายเทคโนโลยีของเรดีเซล เวรนช์ก็ทำถุงมือกลคู่นี้ให้เธอเป็นพิเศษ ถุงมือคู่นี้ช่วยให้อีฟฟื้นตัวได้เร็วขึ้นและเพิ่มความสามารถให้เธอนำทางลูมินาให้ไหลเวียนในร่างกายได้ดีขึ้น",
  str_pet_equip_intro_1501041 = "หลังจากที่ดอว์นตาบอด เธอก็นำกระดิ่งที่พกติดตัวมาตลอดตั้งแต่เด็กมาติดไว้กับคทาของตัวเอง เสียงที่น่ารักของกระดิ่งนี้ทำให้หัวใจของดอว์นสงบได้",
  str_pet_equip_intro_1500711 = "ดาบฟันเลื่อยนี้อาจดูธรรมดา แต่มันเหมาะกับทาคิอย่างมาก และสามารถนำทางพลังแห่งเปลวไฟในร่างกายของทาคิได้",
  str_pet_equip_intro_1701101 = "หอกขนาดใหญ่ที่มีโครงสร้างกลไกซับซ้อน มีธงสีน้ำเงินขาวแห่งการทำลายล้างที่มีตราดวงดาวโบกสะบัดอยู่ด้านบน หอกนี้เป็นอุปกรณ์ที่ช่วยเพิ่มเวทสายฟ้า และสามารถใช้เป็นอาวุธระยะประชิดได้เมื่อศัตรูเข้าใกล้",
  str_pet_equip_intro_1701091 = "คทาหนักขนาดใหญ่นี้เป็นที่เก็บกักพลังเวทมนตร์พิเศษ มิธอสสามารถใช้คทานี้ได้อย่างง่ายดาย และใช้มันเพื่อร่ายคาถาอันทรงพลัง",
  str_pet_equip_intro_1701081 = "หลังจากที่ฟรอสต์ไฟร์ฝึกการใช้คริสตัลวิเศษที่เรียกว่าดวงใจแห่งแม็กม่าจนชำนาญอย่างแท้จริงแล้ว เธอได้ฝังพลังเวทพิเศษไว้ในแส้ยาวนี้ ทำให้สามารถใช้แส้ยาวนี้ร่ายคาถาไฟได้หลายประเภทในการต่อสู้",
  str_pet_equip_intro_1701071 = "ดาบหักขนาดใหญ่ที่ดูเหมือนโลงศพสีเข้ม มีตราดวงดาวและมีความแหลมคม ทำจากโลหะผสมพิเศษลึกลับที่ไม่สามารถทำลายได้ ในขณะเดียวกันก็ติดตั้งอุปกรณ์ที่ช่วยเพิ่มพลังเวทน้ำและลบล้างการโจมตีของศัตรู รวมถึงเปลี่ยนทิศพลังงานจลน์เพื่อให้การปกป้องที่ดีสำหรับผู้ที่ใช้งาน",
  str_pet_equip_intro_1501131 = "เมื่อทรู ออเดอร์ค้นพบความสามารถของโบนาชี วิกตอเรียก็ได้สั่งทำไม้บาตองริบบิ้นไหมชิ้นนี้ให้โดยเฉพาะ เพื่อให้โบนาชีสามารถควบคุมพลังแห่ง \"การช่วยเหลือจากสรวงสวรรค์\" ของเธอได้ และเรียกสมุนอวตารศักดิ์สิทธิ์ของเธอออกมาเพื่อเรียกดาวตก",
  str_pet_equip_intro_1601111 = "คริสตัลแห่งความเบิกบานนี้งอกออกมาจากร่างกายของเธอเหมือนกับดอกไม้ เบริลคิดว่านี่คือแหล่งที่มาของพลังลึกลับของเธอ จึงเก็บไว้กับตัวตลอดเวลาเพื่อความแข็งแกร่ง",
  str_pet_equip_intro_1501141 = "แส้สั้นที่เดิมทีใช้สำหรับขี่ม้า หลังจากที่ความสามารถของเจเนวีฟได้ตื่นขึ้น เธอจึงนำมันมารวมกับพลังแห่งเปลวเพลิงเพื่อสร้างแส้เส้นนี้ขึ้นมา แส้นี้สามารถเผาศัตรูให้เป็นเถ้าถ่านได้ ในขณะที่ด้ามจับโลหะก็สามารถใช้จับตัวเป้าหมายของเธอได้ด้วย",
  str_pet_equip_intro_1601121 = "เข็มกลัดที่ทำจากกระดูกหัวกะโหลกของแมนติคอร์ชิ้นนี้เป็นมรดกประจำตระกูลของสโมกกี้\nที่ทำให้ผู้สวมใส่สามารถควบคุมแมนติคอร์ที่เรียกมาได้ ทั้งยังเพิ่มความชำนาญในการจัดการ\nกับลูมินาติกส์อีกด้วย",
  str_pet_equip_intro_1601161 = "กล่องเครื่องมือพกพาขนาดเล็กที่บรรจุเครื่องมือมากมายหลายประเภท\nเครื่องมือเหล่านี้อยู่กับเฟลอร์มานานหลายปีแล้ว\nและเขามองว่าเครื่องมือทุกชิ้นเป็นส่วนหนึ่งของร่างกายตัวเอง",
  str_pet_equip_intro_1401271 = "กระดาษสีแดงชิ้นพิเศษนี้มีพลังลึกลับแฝงอยู่ และมีความเชื่อมโยงทางจิตใจกับพาโซโล่ พาโซโล่บอกว่ามันทำให้เธอเห็นพ่อแม่ที่ตายไปแล้ว และนำความแข็งแกร่งอย่างยิ่งมาให้เธอได้",
  str_pet_equip_intro_1601171 = "ชุดอาวุธทรงพลังที่รวมเอาดาบใหญ่ รีโวลเวอร์ และฟิสต์เบลดเข้าไว้ด้วยกัน ดาบใหญ่ฟาดฟันหนักหน่วง ล้มได้แม้กระทั่งศัตรูที่แข็งแกร่งที่สุด รีโวลเวอร์และฟิสต์เบลดผสานรวมเข้าด้วยกันเพื่อให้ความยืดหยุ่นในการต่อสู้ โดยให้ผู้ใช้มีทั้งอาวุธมือรองระยะประชิดและอุปกรณ์ยิงกระสุนที่ทรงพลัง",
  str_pet_equip_intro_1601191 = "ดาบใหญ่ที่เรียบง่ายและทนทาน เสริมความแข็งแกร่งด้วยสายเคเบิลเหล็ก ดาบนี้ไม่เพียงแต่เรียกใช้ลูมินาภายในตัวเรวี่ออกมาได้เท่านั้น แต่สายเคเบิลเหล็กยังทำให้เธอขว้างดาบออกไปกำจัดศัตรูในระยะไกลได้อีกด้วย",
  str_pet_equip_intro_1601221 = "ชื่อที่ใช้เรียกนาฬิกาพกและปืนพกของอัลลัวรา นาฬิกาพกขยายสัมผัสรับรู้ของอัลลัวราได้อย่างมาก เพิ่มความแม่นยำและพลังทำลายเวลาที่ใช้ปืนพกโบราณ เมื่อมีสองสิ่งนี้ในครอบครอง ไม่นานเธอก็เป็นที่รู้จักไปไกลในฐานะมือปืนหญิงแห่งอัมบราตัน",
  str_pet_equip_intro_1601211 = "เดิมทีคือตราสัญลักษณ์ศักดิ์สิทธิ์จากวิหารลูโมโพลิส ข้อความแกะสลักได้เปลี่ยนไปหลังจากที่พาโลม่าต้องเห็นพ่อแม่ตายไปต่อหน้าต่อตา มันคือสัญลักษณ์แทนความสิ้นหวังในความศรัทธา และการตัดสินใจที่จะทำตามหัวใจไปบนเส้นทางของตนเอง",
  str_pet_equip_intro_1601151 = "น่าแปลกมากที่นาโรเซลมีเสียงสะท้อนทางวิญญาณตรงกับหิ่งห้อย ทำให้สั่งการแมลงเรืองแสงตัวจิ๋วพวกนี้ให้โจมตีศัตรูได้ กระเป๋าดิ้นทองที่ทำจากผ้าก๊อซโปร่งแสงใบนี้คือที่เก็บสหายตัวน้อย ๆ ของเธอ",
  str_pet_equip_intro_1300651 = "หลังจากได้เป็นผู้ส่งสาร ทวีตตี้ก็บรรจงเย็บขนนกของตัวเองไว้ที่ด้านในของหมวกทรงกระบอก ซึ่งไม่นานก็กลายเป็นเครื่องหมายการค้าของเธอ เมื่อสวมใส่แล้วจะเพิ่มความมีชีวิตชีวาให้แก่ทวีตตี้ได้อย่างมหาศาล",
  str_pet_equip_intro_1601261 = "เบเธลสามารถสลับรูปแบบของอาวุธนี้ระหว่างกระดิ่งกับคทายาว และใช้มันส่งเสียงก้องกังวานเพื่อเรียกแฟรงค์ สุนัขเวทมนตร์ของเธอ",
  str_pet_equip_intro_1601291 = "หลังจากเป็นทหารรับจ้าง ของขวัญชิ้นแรกที่ลุคให้ตัวเองคือผ้าคลุมผืนนี้ เขาวาดลวดลายด้วยตัวเองเพื่อฉลองความทรงจำของเพื่อนผีเสื้อที่เขารัก เสื้อคลุมนี้สามารถเสริมสร้างความสัมพันธ์ของลุคกับมวลแมลง และช่วยให้เขาใช้โซ่ของตนได้อย่างมีศิลปะมากขึ้นในการต่อสู้",
  str_pet_equip_intro_1500551 = "ของที่ระลึกซึ่งผู้เป็นพ่อทิ้งไว้ให้พิตต์แมน อัญมณีสีน้ำเงินที่ฝังอยู่บนยอดมีพลังเรียกสายฟ้า พิตต์แมนสามารถปลดปล่อยความสามารถของคทาในการเรียกพลังสายฟ้าฟาดทำลายล้างใส่ศัตรู",
  str_pet_equip_intro_1601201 = "เฮดี้ไม่ค่อยพกอาวุธนี้ติดตัวเท่าไรและใช้มันแค่ในการต่อสู้เท่านั้น ถึงกระนั้น ความคุ้นเคยของเธอกับดาบเล่มนี้ก็ทำให้เธอสามารถประสานงานกับอัศวินแห่งแสงในการต่อสู้ได้อย่างสมบูรณ์แบบ",
  str_pet_equip_intro_1601231 = "ไม้บาตองแจกจ่ายให้นายอำเภออิลลูมินาเท่านั้น เมื่อเธอเชี่ยวชาญการใช้อาวุธนี้ในที่สุด คอร์ดี้ได้มอบหมายให้ทีมนักวิทยาศาสตร์ดำเนินการเสริมประสิทธิภาพพิเศษกับมัน เพื่อให้สามารถยิงเปลวไฟพร้อมเอฟเฟกต์สตันอันทรงพลังที่ช่วยทำให้เป้าหมายของเธอไร้ทาง\nป้องกันตัวได้อย่างง่ายดาย",
  str_pet_equip_intro_1500151 = "ย่อมาจาก \"บาดา บิง บาดา บูม\" ชื่อรวมที่ฮาชิและกินตั้งให้กับอาวุธประเภทต่าง ๆ ที่พวกเขาพกติดตัว ซึ่งประกอบด้วยเครื่องยิงลูกระเบิด ปืนไรเฟิลจู่โจมพิเศษ และระเบิดมือ มีข่าวลือว่าพวกเขาได้ทรัพย์สินนับล้านโดยใช้อาวุธเหล่านี้เพื่อตั้งรกรากและสร้างชีวิตให้กับตัวเอง",
  str_pet_equip_intro_1601311 = "คทายาวนี้ว่ากันว่าทำจากไพลินของภูตแห่งขุนเขาตัวแรก ซึ่งสามารถเพิ่มความแข็งแกร่งภายในของผู้ใช้งานและปลดล็อกศักยภาพที่ซ่อนอยู่ได้",
  str_pet_equip_intro_1501321 = "เดิมทีเป็นเถาวัลย์ธรรมดาจากป่าลู่ลม ตอนที่โลล่าบังเอิญหลงเข้าไปในป่าและนอนทับ ลูมินาที่ไหลเวียนจากร่างกายของเธอได้ทำให้มันกลายเป็นคันธนู เมื่อโลล่าใช้ลูมินาติกส์จนชำนาญแล้ว ในที่สุดมันก็กลายมาเป็นอาวุธประจำตัวของเธอ",
  str_pet_equip_intro_1601331 = "ชุดเมดที่แปลงมาจากเกล็ดของโทรุ โทรุเลือกที่จะเป็นสาวใช้ของโคบายาชิด้วยความรัก สำหรับเธอแล้ว นี่ไม่ใช่แค่ชุดทำงานธรรมดา",
  str_pet_equip_intro_1601341 = "เครื่องประดับที่ตกแต่งผมของคันนะจัง ที่จริงเป็นโบราณวัตถุที่สามารถควบคุมมังกรทั้งหลายด้วยการปล่อยพลังเวทที่อยู่ภายใน",
  str_pet_equip_intro_1501361 = "หมวกสั่งทำที่ลูโคอาใส่ มีรูไว้ให้เขาลอดออกมาได้ เธอมักจะใส่ไว้ตลอดเวลาเพราะถอดออกยาก",
  str_pet_equip_intro_1501351 = "ตรีศูลที่มีพลังแห่งท้องทะเลสิงสถิตอยู่ เมื่ออยู่ในมือเอลมาจะปล่อยพลังมหัศจรรย์แห่งน้ำได้",
  str_pet_equip_intro_1401371 = "แว่นตาวินเทจที่ออกแบบตามสไตล์ผู้สวมใส่ โดยใช้ภาพตัวอย่างที่โทรุให้มา",
  str_pet_equip_intro_1601381 = "เชอวานบังเอิญพบกระดานจดบันทึกนี้ขณะสำรวจซากปรักหักพัง มันทำจากวัสดุพิเศษที่ใช้เป็นเครื่องมือจดบันทึกแบบพกพา ต่อมาเธอพบว่าเธอสามารถใช้ลูมินาติกส์เพิ่มความทนทานของกระดานจดบันทึกได้ ด้วยเหตุนี้มันจึงกลายเป็นอุปกรณ์ป้องกันของเธอ",
  str_pet_equip_intro_1501391 = "ดาบบางเฉียบที่ออกแบบมาเป็นพิเศษให้เบากว่าปกติ มันสามารถเป็นสื่อนำลูมินาในร่างกายของเอริก้าได้ดี ทำให้เธอสามารถปล่อยสายฟ้าอันทรงพลังในการต่อสู้",
  str_pet_equip_intro_1601401 = "ดาบเล่มนี้มีรูปทรงคดเคี้ยวซึ่งไม่ค่อยพบเห็นในลูโมโพลิสหรือแม้แต่ทั่วทั้งทวีป พ่อแม่ทำพิเศษสำหรับเธอโดยเฉพาะ ไม่เพียงแต่ทนทาน มันยังคมกริบอีกด้วย ทำให้ฟลอรีนสามารถใช้ลูมินาติกส์ได้อย่างทรงพลังมากยิ่งขึ้น",
  str_pet_equip_intro_1601411 = "ไม้เบสบอลที่พบเจอในกองอะไหล่ที่เรดีเซล เวรนช์ คาดเดาว่าน่าจะทำจากวัสดุพิเศษบางอย่าง รูบี้ใช้เวลาไม่นานก็พบว่ามันเหมาะกับเธอที่สุด และมันยังเสริมให้ลูมินาติกส์ของเธอแข็งแกร่งขึ้นอีกด้วย",
  str_pet_equip_intro_1501421 = "อาวุธที่รูจทำขึ้นมาเอง มันมีแม็กกาซีนที่บรรจุกระสุนได้หลายชนิด แถมรูจยังสามารถใช้ลูมินาจุดระเบิดให้กระสุนที่ยิงออกไปแล้วด้วย ส่วนคีมก็ยิงลวดทองแดงออกไปเกี่ยวศัตรูได้",
  str_pet_equip_intro_1601431 = "ตราสัญลักษณ์บนพัดเล่มนี้อาจดูธรรมดาสำหรับคนทั่วไป แต่มีความหมายลึกซึ้งยิ่งนักสำหรับรินเนะ ไม่เพียงแต่ทำให้เธอเห็นไอพลังงานของผีเท่านั้น แต่ยังเสริมพลังการควบคุมผีสางของเธอด้วย",
  str_pet_equip_intro_1501441 = "หลังจากพิธีกรรมลึกลับนั้น คายาโนะก็เห็นผีที่อยู่ในริบบิ้นนี้อยู่ตลอด เมื่อไม่สามารถขับไล่มันไปได้ เธอก็ได้แต่ยอมรับมันและใช้ให้เป็นประโยชน์โดยการนำมาเพิ่มพลังให้กับเธอ",
  str_pet_equip_intro_1601461 = "ปลอกแขนที่กิลด์หลินออกแบบและพัฒนาสำหรับเหยาโดยเฉพาะ หลังจากการดูแลเป็นพิเศษ ไหมที่ทออย่างประณีตจะนุ่มและแน่น ทำให้เธอชกได้โดยไม่เสี่ยงต่อการบาดเจ็บ ที่สำคัญคือเข้ากับชุดของเธอได้อย่างลงตัว",
  str_pet_equip_intro_1601451 = "อาเมโมริได้ขนของสะสมที่เป็นความลับมาตั้งแต่วันแรกที่เธอฝึกวิชานินจา อันที่จริงแล้ว มันไม่ใช่แค่อาวุธและเครื่องมือนินจาเท่านั้น แต่ยังรวมถึงวัตถุอื่นๆ ที่คนส่วนใหญ่ไม่เคยได้ยินมาก่อนด้วย พวกเขาช่วยกันทำให้มั่นใจว่าอาเมโมริสามารถทำภารกิจใด ๆ ให้สำเร็จได้",
  str_pet_equip_intro_1501471 = "ชุดเครื่องครัวที่โมโมะและอันสึพกติดตัวไปทุกที่ชนิดที่ขาดไม่ได้ พวกเธอจำเป็นต้องใช้สิ่งเหล่านี้ในการทำอาหารอย่างรวดเร็วแต่อร่อย และยังใช้จัดการกับพวกอันธพาลที่รบกวนการทำอาหารของพวกเธออีกด้วย",
  str_pet_equip_intro_1201631 = "กระดานที่ใช้บอกเวลาเริ่มงาน เปล่งเสียงอันคมชัดอย่างที่ Tourdog มองว่าเป็นเพลงที่ไพเราะที่สุดในโลก ทุกครั้งที่เสียงนี้ดังขึ้น นั่นหมายความว่า Tourdog กำลังเข้าใกล้ความฝันของเขาอีกก้าวหนึ่งแล้ว...",
  str_pet_equip_intro_1601481 = "ปืนไรเฟิลนี้ว่ากันว่าค้นพบในซากโบราณลึกลับ และมาอยู่ในมือแอเชอร์ตั้งแต่ตอนที่เธอยังเด็ก มันจะเปล่งสีน้ำเงินเข้มสวยงามเมื่อต้องแสงอาทิตย์โดยตรงและใช้ยิงกระสุนชนิดพิเศษได้",
  str_pet_equip_intro_1501491 = "กระเป๋าขนาดเล็กที่มีเครื่องมือมากมาย ทั้งระเบิด อุปกรณ์สำหรับผึ้งน้ำหวานกล และลูกอมที่รอยพกติดตัวตลอดเวลา",
  str_pet_equip_intro_1601501 = "เดิมทีมันก็เป็นแค่ไม้ธรรมดาอันหนึ่ง แต่เมื่อมาอยู่ในมือของเลนอร์ ได้รับเลือดที่เธอหยดลงไปผสานกับลูมินาติกส์พิเศษของเธอ มันจึงกลายเป็นเคียวขนาดใหญ่ที่พิฆาตศัตรูได้ทั้งหมด",
  str_pet_equip_intro_1601511 = "ตอนที่ไจลส์พบกับไอแซค แกะดำของเขา เขาถือไม้เท้านี้อยู่ในมือ และต่อมาได้กลายเป็นเครื่องมือที่เขาใช้สื่อสารกับไอแซค ทำให้เขาเรียกและสั่งการมันได้",
  str_pet_equip_intro_1501521 = "ดูเหมือนจะเป็นกระเป๋าสะพายเก่า ๆ ที่มีการปะชุนมากมาย หน้าตาคล้ายแมวหกตาที่แปลกประหลาด แต่มันเป็นของรักของเมย์ และเธอก็พกติดตัวเสมอไม่เคยคลาดจากสายตาเลย",
  str_pet_equip_intro_1601531 = "หอกนี้มีสีแดงราวกับกำลังลุกไหม้ มันอยู่เคียงข้างไรน์ฮาร์ตในยามที่เธอเผชิญวิกฤตมากมายและรอดชีวิตจากการสู้รบที่มีความเป็นและความตายเป็นเดิมพันมานับครั้งไม่ถ้วน ตอนนี้ไรน์ฮาร์ตเชี่ยวชาญการใช้หอกนี้อย่างเต็มที่แล้ว",
  str_pet_equip_intro_1601541 = "หน้าไม้ที่พบท่ามกลางโบราณวัตถุสามารถยิงลูกศรติดต่อกันได้อย่างฉับไว ด้วยลูมินาติกส์ของไวซ์และเทคนิคการต่อสู้ที่เรียนรู้ใหม่ ทำให้เธอเล็งจุดสำคัญของเป้าหมายได้อย่างแม่นยำและทำให้บาดเจ็บสาหัสถึงชีวิต",
  str_pet_equip_intro_1601551 = "เดิมทีเป็นดาบสองเล่มที่แยกกัน แต่นำมารวมกันเป็นดาบสองคมได้เมื่อจำเป็น บาร์ตันแกว่งไกวดาบนี้ราวกับเป็นสายลมในมือที่พัดพาศัตรูกระเด็นไปจนหมดสิ้น",
  str_pet_equip_intro_1601561 = "อาจฟังดูเหมือนชื่อสถานที่ แต่มันคือร่มกันแดดสีดำที่นีน่าพกติดตัว เมื่อใช้ลูมินาติกส์ นีน่าสามารถเรียกอาวุธทุกชนิดออกมาจากร่มนี้ได้",
  str_pet_equip_intro_1501571 = "ริบบิ้นที่ซานาเอะพกติดตัวตลอดเวลา ไม่เพียงแต่เป็นตัวนำที่ซานาเอะใช้ส่งลูมินาไปโจมตีศัตรูเท่านั้น แต่ยังใช้ควบคุมหุ่นเชิดของเธอให้ต่อสู้ได้อีกด้วย",
  str_pet_equip_intro_1601581 = "อาวุธของโจ๊กเกอร์\nลักษณะเหมือนกริช",
  str_pet_equip_intro_1501621 = "อาวุธของโมน่า\nลักษณะเหมือนดาบที่พวกโจรชอบใช้กัน",
  str_pet_equip_intro_1501601 = "อาวุธของฟ็อกซ์\nมีรูปร่างเหมือนคาตานะ",
  str_pet_equip_intro_1601591 = "อาวุธของควีน\nดูแล้วคล้ายกับนวมชกมวย",
  str_pet_equip_intro_1501611 = "อาวุธของไวโอเล็ต\nลักษณะเหมือนดาบเรเปียร์ที่คมกริบ",
  str_pet_equip_intro_1501681 = "หลังจากที่เรนโบว์ได้อาศัยอยู่บนเรือมรกต วิศวกรของเรือก็สร้างปืนฉีดน้ำแรงดันสูงให้เธอ แม้ว่าจะดูธรรมดามาก แต่ปืนนี้สามารถปรับแรงดันเพื่อฉีดน้ำให้แรงหรือเบาได้ตามต้องการ และสามารถระเบิดพลังมหาศาลออกมาเมื่อใช้กับลูมินาติกส์ของเรนโบว์",
  str_pet_equip_intro_1601661 = "ปืนยิงสัญญาณที่ดัดแปลงแล้ว มีขนาดเล็ก คล่องตัว และใช้งานง่าย สามารถยิงระเบิดขนาดเล็กใส่ศัตรูเพื่อโจมตี และยังยิงเครื่องหมายเพื่อนำทางสัตว์ที่ได้รับการฝึกฝนแล้วให้มาโจมตีได้อีกด้วย",
  str_pet_equip_intro_1601671 = "สำรับไพ่ที่ทำขึ้นเป็นพิเศษโดยมีพลังลึกลับของ \"ต้นกำเนิด\" สถิตอยู่ภายใน วิกตอเรียมอบไพ่สำรับนี้ให้กับเจโน่ในตอนที่เขาเข้าร่วมเป็นสมาชิกทรู ออเดอร์ ทักษะการควบคุมไพ่ที่ยอดเยี่ยมของเจโน่ทำให้เขาเปิดใช้พลังของไพ่ และแสดงพลังเวทมนตร์ได้ทุกประเภท",
  str_pet_equip_intro_1501651 = "เซียลใช้ประแจนี้ในครั้งแรกได้อย่างชำนาญโดยไม่ต้องมีครูสอน หลังจากนั้นเซียลก็ใช้ประแจนี้ประกอบหุ่นยนต์ไดนามิกสองชุดได้สำเร็จ และยังซ่อมแซมชิ้นส่วนสำคัญได้ในยามฉุกเฉิน... สำหรับเซียลแล้ว ประแจนี้ไม่ใช่แค่เครื่องมือธรรมดา แต่เป็นการต่อยอดงานประดิษฐ์ของเธอ",
  str_pet_equip_intro_1601641 = "คาร์ลีนบังเกิดความเข้าใจสิ่งใหม่หลังจากการเดินทางในครั้งนั้น และหอกเล่มนี้ก็ได้รับความสามารถที่แตกต่างไปจากเดิม แม้แต่สัญลักษณ์ประจำตัวบนหอกก็เปลี่ยนไปด้วยเช่นกัน! หมดข้อกังขาเลยว่าคาร์ลีนมีความชำนาญในการใช้หอกเล่มนี้อย่างไม่มีใครเทียบได้",
  str_pet_equip_intro_1501301 = "ไม่มีคำใดในประมวลกฎหมายพิเศษนี้ อันที่จริงไม่ได้มีไว้สำหรับการอ่าน แต่สำหรับ \"การต่อสู้\" มีเพียงเจ้าของเท่านั้นที่รู้วิธีใช้งาน",
  str_pet_equip_intro_1501711 = "ปืนไรเฟิลนี้มีใบมีดขนาดใหญ่และแข็งแรง ไม่ส่งผลต่อความแม่นยำในการยิง และมีประโยชน์ในการต่อสู้ระยะประชิด",
  str_pet_equip_intro_1601701 = "ว่ากันว่าเป็นหนึ่งในปืนพกสุดโปรดของพอลลักซ์ มีความแข็งแรงทนทานและทรงพลัง เธอสามารถเสริมประสิทธิภาพกระสุนด้วย Luminatics ของเธอ ทำให้พวกมันลงจอดบนเป้าหมายที่มีผลกระทบมากขึ้น",
  str_pet_equip_intro_1401691 = "หลังจากภารกิจบางอย่างและตามคำสั่งของเพื่อน Sadie หยิบอาวุธที่เหมาะกับสไตล์การต่อสู้ของเธออย่างสมบูรณ์แบบ นั่นคือ ไม้เบสบอลดัดแปลง หลังจากการฝึกฝนอย่างเข้มงวดและต่อเนื่อง ในที่สุด Sadie ก็สามารถใช้ความแข็งแกร่งของไททานิคผ่านไม้ตีที่ไว้ใจได้ของเธอ และส่งศัตรูที่บินได้ เธอยังสามารถส่งรถสูงเสียดฟ้าได้!",
  str_pet_equip_intro_1601721 = "กล้องวิดีโอตัวแรกของ Lilica และของขวัญอันเป็นที่รักจากพ่อแม่ของเธอ แม้จะเป็นกล้องมือสอง แต่เธอก็รักมันเหนือสิ่งอื่นใด หลังจากควบคุมฟังก์ชั่นต่าง ๆ ของมันแล้ว Lilica ยังสามารถปรับปรุงด้วย Luminatics ของเธอเพื่อยิงได้ทุกที่ทุกเวลา แม้แต่ในสนามรบ สิ่งนี้ทำให้พันธมิตรของเธอได้รับการสนับสนุนที่จำเป็นมากในการต่อสู้",
  str_pet_equip_intro_1601731 = "ในความเป็นจริง มันเป็นแค่ปืนพกแบบฟลินล็อคธรรมดา อย่างไรก็ตาม ภายใต้การดูแลอย่างพิถีพิถันของ Minos เขาสามารถใช้ Luminatics เพื่อปลดปล่อยพลังเดิมได้หลายเท่า",
  str_pet_equip_intro_1501761 = "ชื่อรวมของ \"Borealis\" และ \"Australis\" \"Borealis\" เป็นหอกสองใบมีดในขณะที่ \"Australis\" เป็นหอกยาว ความแข็งแกร่งอันน่าทึ่งของเบเร็ตต้าทำให้เธอแกว่งอาวุธยาวทั้งสองนี้ได้อย่างง่ายดาย ซึ่งทหารทั่วไปต้องใช้มือทั้งสองข้างด้วยมือเดียว เธอยังสามารถขว้าง \"Australis\" เพื่อโจมตีระยะไกลได้อีกด้วย",
  str_pet_equip_intro_1601751 = "แม้ว่าหุ่นยนต์เหล่านี้จะดูเหมือนกันทั้งหมด แต่ Axelia จะไม่มีวันผสมพวกมันเข้าด้วยกัน สร้างโดยสหพันธ์อิลลูมินาโดยเฉพาะเพื่อการใช้งานของ Axelia ซึ่งสามารถรองรับอาวุธได้มากมายและสามารถช่วยเธอในการต่อสู้ได้",
  str_pet_equip_intro_1601771 = "นี่คือไมโครโฟนที่ Goldie ใช้ในระหว่างการแสดง ทำจากโลหะมีค่าประสานกับความสามารถพิเศษของเธอในการส่งเสียงร้องของเธอไปยังหูของผู้ฟังทุกคน เพื่อให้เพลงของเธอสามารถปัดเป่าหมอกหนาทึบในหัวใจทั้งหมด",
  str_pet_equip_intro_1601781 = "แม้จะดูเหมือนไม้ค้ำเดินป่าทั่วไป แต่ก็แข็งแรงพอที่จะใช้เป็นอาวุธได้ ในกรณี... มันมีสัตว์แปลก ๆ ที่โจมตีศัตรูเมื่อหลุดออกไป",
  str_pet_equip_intro_1501801 = "มันอาจเป็นแค่กล้องสำหรับนักข่าวมือใหม่ แต่ Brandy สามารถใช้มันได้อย่างเชี่ยวชาญเพื่อถ่ายภาพทุกประเภทและค้นหาจุดอ่อนของศัตรูเพื่อที่เธอจะได้กำหนดเป้าหมายพวกเขา",
  str_pet_equip_intro_1501831 = "Liqing ใช้เครื่องชั่งนี้เพื่อชั่งน้ำหนักสมุนไพรตั้งแต่เรียนรู้ศิลปะการรักษา การวัดที่แม่นยำช่วยให้เขาแบ่งส่วนที่ถูกต้องและสมบูรณ์แบบทุกครั้ง ความรู้ด้านการแพทย์ของ Liqing ดีขึ้นเมื่อเขาเชี่ยวชาญการใช้เครื่องชั่งมากขึ้น",
  str_pet_equip_intro_1601821 = "กริชนี้ถูกกล่าวหาว่าสร้างขึ้นจากกระดูกของบรรพบุรุษคนหนึ่งของ Yuebai มันมีพลังในการตัดและแทงที่มหาศาล เธอมีสายสัมพันธ์ลึกลับกับมัน เธอใช้มันอย่างแม่นยำตั้งแต่วินาทีแรกที่เธอจับมัน ต่อมาได้กลายเป็นอาวุธประจำตัวของเธอ",
  str_pet_equip_intro_1601811 = "Zhong Xu ได้รับแหวนนี้หลังจากสืบทอด Flame Force Arts ของครอบครัวเพื่อเป็นสัญลักษณ์แห่งการยอมรับของตระกูล เมื่อใดก็ตามที่ความคิดในการเลิกหรือเลิกใช้พื้นผิวในตัวเขา รอยแตกจะปรากฏในวัตถุ เนื่องจากแหวนทำให้อารมณ์ส่วนตัวของเขาเป็นที่ประจักษ์ต่อผู้อื่น เขาจึงไม่ค่อยแสดงให้ใครเห็น",
  str_pet_equip_intro_1601841 = "ของที่ระลึกที่เหยี่ยวและงูเหลือมศักดิ์สิทธิ์มอบให้กับเยรีอาห์ กล่าวกันว่าเป็นขนและเกล็ดแรกที่พวกมันเติบโตอย่างเคารพนับถือ ซึ่งบ่งชี้ถึงความไว้วางใจอย่างแท้จริงที่มีต่อเยรียาห์ มันปรับปรุงเคมีของพวกเขากับเธอในการต่อสู้",
  str_pet_equip_intro_1501851 = "เมื่อ Kya กลายเป็นคนส่งเอกสาร เธอก็ถืออาวุธนี้ไว้ข้างตัวแล้ว และมันก็ช่วยเธอได้อย่างดีตั้งแต่นั้นมา กับเธอในการส่งจดหมายทั่วโลกอย่างปลอดภัย เธอยังคงถือหน้าไม้นี้ต่อไป โดยเชื่อว่าตราบเท่าที่เธอมี แม้ว่าจะมีอันตรายเกิดขึ้นระหว่างการทำงาน เธอก็ยังส่งได้ทันเวลา",
  str_pet_equip_intro_1601861 = "ทีน่าเกิดในตระกูลขุนนาง มีพรสวรรค์ด้านดาบมาตั้งแต่เด็ก ดาบยาวเล่มนี้ติดตามเธอมาเป็นเวลานาน ด้วยดาบนี้เท่านั้นที่เธอสามารถใช้พลังงาน Lumina เฉพาะที่เธอเชี่ยวชาญได้ถึงขีดจำกัดของมัน",
  str_pet_equip_intro_1601891 = "แม้ว่ามันจะไม่เหมือนกับอาวุธที่อัศวินใน Lumopolis ใช้กันทั่วไป แต่ Leyn ผู้ซึ่งสนใจเกี่ยวกับการใช้งานจริงของอาวุธมากกว่ารูปลักษณ์ของมัน ไม่ได้สนใจมันเลย ซึ่งสะท้อนถึงบุคลิกของเขาไม่มากก็น้อย... Leyn สามารถใส่ Luminatics เข้าไปได้ อาวุธนี้จะทำให้หมุนอย่างต่อเนื่อง เร่งความเร็ว และเปิดใช้งานสวิตช์เพื่อให้ Lumina พุ่งออกมาเพื่อทำลายศัตรูของเขา",
  str_pet_equip_intro_1501901 = "โดยปกติจะเป็นไม้เท้า มันจะกลายเป็นแส้ยาวเมื่อ Matthieu ใส่ Lumina เปลวเพลิงลุกลามไปทั่ว ปล่อยแสงเจิดจ้าเตือนผู้กระทำผิดไม่ให้เข้าใกล้ คนที่กล้าหาญพอที่จะลองชิมจะได้ลิ้มรสความเจ็บปวดของความสำนึกผิด",
  str_pet_equip_intro_1501931 = "Kristen สามารถใช้หอกนี้ได้ตั้งแต่ครั้งแรกที่เธอได้รับการฝึกฝนศิลปะการต่อสู้ และสามารถใช้ Lumina เพื่อเพิ่มพลังของมันได้ เธอยังสามารถใช้มันเพื่อควบคุมน้ำ เรียกกระแสน้ำอันทรงพลังที่สามารถแยกคลื่นที่โหมกระหน่ำได้",
  str_pet_equip_intro_1601911 = "ตราหัวม้าบนล็อกเกตทำให้ดูล้ำค่าอย่างยิ่ง มีข่าวลือว่าทำจากทองคำบริสุทธิ์! กลไกอันวิจิตรงดงามภายในนั้นต้องใช้ Hati และอีกคนหนึ่งเปิดมันพร้อมกัน",
  str_pet_equip_intro_1601921 = "แม้ว่าดาบของ Leo อาจดูไม่มีอะไรพิเศษเมื่อเทียบกับอาวุธในตำนานเหล่านั้น แต่เมื่ออยู่ในมือของเขา มันกลายเป็นสัญลักษณ์ที่มีอำนาจเหนือผู้คนของเขา นี่อาจเป็นเพราะความสามารถพิเศษโดยกำเนิดของลีโออย่างน้อยในบางส่วน",
  str_pet_equip_intro_1601991 = "ไรเฟิลซุ่มยิงนี้โดดเด่นกว่าปืนทั่วไปเนื่องจากวัสดุและโครงสร้างที่เป็นเอกลักษณ์ ซึ่งสร้างขึ้นอย่างพิถีพิถันโดยแผนกเฉพาะสำหรับ Yingel แม้แต่ผู้ที่ไม่คุ้นเคยกับอาวุธปืนก็สามารถตรวจจับร่องรอยของการดัดแปลงอาวุธพิเศษนี้ได้อย่างชัดเจน",
  str_pet_equip_intro_1502001 = "สมุดบันทึกเก่าที่อนาโตลีบันทึกข่าวกรองทั้งหมดที่เขารวบรวมได้เมื่อเวลาผ่านไป แม้ว่าจะมีป้ายกำกับและแท็กต่างๆ ครอบคลุมอยู่ และคุณอาจได้เห็นดูเดิลของอนาโตลีบ้างเป็นครั้งคราว",
  str_pet_equip_intro_1602011 = "เจ้าหน้าที่ Mia ถืออาวุธในช่วงเวลาที่เธออยู่กับ Lumo Knights ในขั้นต้น Mia ให้ความสนใจเพียงเล็กน้อยกับมัน อย่างไรก็ตาม ขณะที่เธอสวมชุดเก่าของเธอและเรียกคืนโบราณวัตถุนี้จากอดีต เธอก็ตระหนักถึงพลังอันน่าทึ่งในการสำแดงความแข็งแกร่งของเธออย่างสมบูรณ์แบบ โดยดึงเอาความสามารถทั้งในอดีตและปัจจุบันของเธอมาใช้อย่างง่ายดาย",
  str_pet_equip_intro_1602021 = "ชวาร์ตษ์มีทักษะอันน่าทึ่งในการกวัดแกว่งดาบขนาดมหึมา ซึ่งมีชื่อเสียงในด้านน้ำหนักที่น่าเกรงขามและธรรมชาติที่ท้าทายให้ผู้อื่นจัดการ ด้วยการฝึกฝนอย่างทุ่มเทและความเชี่ยวชาญด้าน Luminatics เขาจึงใช้อาวุธอันทรงพลังนี้ได้อย่างง่ายดาย นอกจากนี้ เขายังควบคุมพลังของ Luminatics เพื่อสร้างใบมีดที่คล้ายกัน ทำให้เขาสามารถโจมตีศัตรูอย่างรุนแรง ได้เปรียบในการต่อสู้ และในที่สุดก็ได้รับชัยชนะในความพยายามของเขา",
  str_pet_equip_intro_1502031 = "หนังสือเล่มหนาและมีน้ำหนักที่โบอาสแม่ของเธอทิ้งไว้ ผู้มีชื่อเสียงในฐานะนักทำนายที่มีทักษะมากที่สุดในนอร์ธแลนด์ หนังสือทรงคุณค่าเล่มนี้ประกอบด้วยผลการวิจัยที่กว้างขวางของโบอาสและประสบการณ์อันหลากหลายของเธอ โดยพื้นฐานแล้ว มันทำหน้าที่เป็นแหล่งข้อมูลอันมีค่าในการเสริมความสามารถในการทำนายของ Jakine โดยให้ความช่วยเหลือที่สำคัญในการปฏิบัติของเธอ",
  str_pet_equip_intro_1502051 = "เธอควงเคียวขนาดใหญ่และหนักพอๆ กับที่เธอใช้ช้อนคน เมื่อมีอาวุธร้ายแรงอยู่ในมือ การต่อสู้ของเธอจึงกลายเป็นเรื่องสบายๆ ราวกับนั่งดื่มชายามบ่าย ด้วยรอยยิ้ม เธอส่งศัตรูของเธออย่างง่ายดายภายใต้กระแสสีแดงเข้มของการโจมตีอย่างไม่หยุดยั้ง",
  str_pet_equip_intro_1602041 = "ดาบทู่นี้ไม่ได้มีไว้สำหรับตั้งโชว์เท่านั้น เมื่อได้รับพลังจาก Joshua's Luminatics โดยเฉพาะอย่างยิ่งความเชื่อมั่นของเธอที่จะปกป้องครอบครัวของเธอ มันพลุ่งพล่านด้วยพลังที่นึกไม่ถึง",
  str_pet_equip_intro_1602061 = "ด้านหลังของทุกความสำเร็จในธุรกิจคือกระแสความคิดที่ไม่หยุดนิ่ง! เมื่อธุรกิจของ Lorelei ประสบปัญหา คุณจะเห็นเธอถือปืนพก ยิงด้วยกระสุนความคิด และฟังเสียงคลิกของเข็มยิง มากกว่านั้น ความคิดใหม่ๆ ก็เกิดขึ้น ทำให้ปืนพกนี้เป็นอาวุธที่ Lorelei หันไปใช้เสมอ",
  str_pet_equip_intro_1602071 = "ความสำคัญของสุภาพบุรุษที่แท้จริงคือความสามารถในการรักษาความสง่างามและแต่งกายอย่างเหมาะสมในทุกๆ โอกาส ในการต่อสู้ เขาประดับตัวเองด้วยหมวกและปืนนี้ ซึ่งในความเป็นจริงแล้วเป็นเพียงชิ้นประดับเท่านั้น ไม่ใช่อาวุธที่ใช้งานได้จริง ๆ - เขาเชื่อว่าการกระทำดังกล่าวจะสร้าง \"บรรยากาศการต่อสู้\"",
  str_pet_equip_intro_1502081 = "ข่าวลือกล่าวว่าโซ่เหล็กแข็งแรงนี้เคยถูกใช้ในการผูกกิ้งก่ายักษ์ร้ายก่อนที่บ็อปเปอร์จะเป็นสมาชิกของเรดีเซล เวรนช์ ถึงแม้ว่ามันอาจจะเป็นเรื่องโกหก โซ่เหล็กนี้ยังคงเป็นที่ยอมรับในความทนทาน! มันสามารถทนต่อการโบกร่อนและการตีที่มีพลังของบ็อปเปอร์ได้ง่ายๆ",
  str_pet_equip_intro_1602091 = "สร้างขึ้นจากการประกอบกันของอาร์เรย์เครื่องบินเดิม หอกนี้สัมผัสกับจิตวิญญาณของวราธอย่างลึกซึ้ง ความสัมพันธ์ที่แท้จริงกับวราธทำให้มันเป็นส่วนขยายของแขนและความตั้งใจของเธอ เมื่อถูกขับเคลื่อนด้วย Luminatics ของเธอ มันสามารถกำจัดศัตรูทั้งหมดในการต่อสู้ระยะประชิด และยังสามารถโยนออกไปเหมือนหอกเพื่อทะลุกลุ่มศัตรู",
  str_pet_equip_intro_1502101 = "เหมือนกับพรหมลิขิตของผู้ใช้งาน ดาบเรเปียร์นี้เริ่มต้นเป็นอาวุธธรรมดาที่ใช้ในการฝึกฝนประจำวันของโจเซลีน อย่างไรก็ตาม หลังจากโจเซลีนใช้มันป้องกันเมืองทไวไลท์ ดาบเรเปียร์ดูเหมือนจะได้รับพลังความลึกลับจากโลกอื่น ทุกครั้งที่โจเซลีนจับ คมดาบไม่เคยคลุ้ม ไม่เคยหัก คงไว้อยู่กับความคมกริบที่ไม่เปรียบเทียบได้ตลอดไป",
  str_pet_equip_intro_1602121 = "ไม้ค้ำปีนเขาหลายฟังก์ชันที่สร้างจากวัสดุที่ Antony เก็บเองเป็นเครื่องมือที่ขาดไม่ได้ในการเดินทางของเขา ในกระบวนการผลิต ความทนทานเป็นความสำคัญเดียว ทำให้มีลักษณะที่ไม่น่าประทับใจ หลังจากปรับปรุงหลายครั้ง ตอนนี้มาถึงรุ่นที่เจ็ด มีฟังก์ชันเช่น เครื่องส่งสัญญาณ ไฟ และเรดาร์พื้นฐาน",
  str_pet_equip_intro_1602111 = "เมื่อซาร์ย่าหลุดพ้นจากเมฆควันของอดีต เธอพบว่ามันไม่ใช่กรงน้ำแข็งที่จับกังวลเธออีกต่อไป แต่เป็นพลังที่เติบโตอย่างอิสระในมือของเธอ คริสตัลน้ำแข็งที่เธอหนาวเข้า ส่องแสงฟลูออเรสเซนต์คล้ายกับผมที่สว่างของเธอ เป็นเพียงหิมะที่ถูกเปลี่ยนรูป ซึ่งสร้างขึ้นด้วยหัวใจที่มีความมุ่งมั่นมากขึ้น",
  str_pet_equip_intro_1502131 = "แขนกลหลายข้อต่อเหล่านี้เป็นประเภทที่น่าสนใจของอวัยวะที่ติดตั้งบนร่างกาย No. 33 ซึ่งมีความยืดหยุ่น สะดวก และร้ายแรงกว่าแขนของออโรเรียนเฉลี่ย พวกเขาสามารถถือเครื่องมือซ่อมบำรุงหลายชิ้นพร้อมกันเพื่อทะลุโครงสร้างเครื่องกลและดำเนินการบำรุงรักษา นอกจากนี้ยังสามารถติดตั้งคีบและประจุไฟฟ้าเพื่อทะลุกำแพงป้องกันของศัตรู",
  str_pet_equip_intro_1501871 = "Li Tianxian พกธงยาวที่เค้าว่าจะช่วยเขาในการทำนาย แต่หน้าที่หลักของมันคือการดึงดูดลูกค้าที่มีศักยภาพหลากหลาย อย่างไรก็ตาม ธงนี้ไม่ควรถือเบาใจ - ในสนามรบ Li Tianxian สามารถใช้มันปล่อย Luminatics ที่ไม่เหมือนใคร ร่วมกับเพื่อนนกของเขา เพื่อโจมตีศัตรูจากที่ที่ไม่คาดคิด",
  str_pet_equip_intro_1601881 = "พิปาที่มีช่วงเสียงกว้างมาก สามารถแสดงความรู้สึกหลากหลายได้ ดันตังยังค้นพบว่ายิ่งเธอเล่นมันมากขึ้น ควบคุมลูมินาของเธอก็ยิ่งแข็งแกร่งขึ้น ดังนั้นเธอจึงเลือกพกพามันไปทุกที่ที่เธอไป",
  str_pet_equip_intro_1602141 = "ความสามารถพิเศษที่เรเบคก้าเกิดมาพร้อม ช่วยปกป้องเธอจากความอันตรายที่อาจเกิดขึ้น และให้พลังในการปกป้องคนที่เธอรักด้วย แต่สิ่งเดียวที่ไม่ชัดเจนสำหรับเรเบคก้าคือ พลังนี้เป็นพรหรือคือคำสาป...",
  str_pet_equip_intro_1502151 = "อีซ่าจ่ายเงินมากมายเพื่อซื้อแส้ที่เป็นที่รักของเธอ - อาวุธที่ให้ผลสู้ดีในสนามรบและทำให้เหยื่อประสบความเจ็บปวดที่ไม่สามารถทนได้ เธอชอบอาวุธนี้มากและได้สำรวจการใช้งานที่หลากหลายของมันจนถึงขีดจำกัด รวมถึงการใช้งานที่เธอชื่นชอบเป็นพิเศษ - การตีและมัด แน่นอนว่าอาวุธนี้ยังมีการใช้งานที่สำคัญที่สุดเหนือกว่าการใช้งานอื่น ๆ - คือการปกป้องเรเบคก้า",
  str_pet_equip_intro_1602161 = "ร่มล้อเกียร์ที่เป็นที่ชื่นชอบของซวนจี ซึ่งรวมความสามารถของโรงเรียนช่างศิลป์ในอาณาจักรเย่ มีความคล่องแคล่วและหลากหลายเหมือนสัตว์ และเป็นพกพาและง่ายต่อการถอดประกอบเหมือนวัตถุที่ไม่มีชีวิต สามารถเก็บนกเครื่องลานและนกเครื่องลานที่ทำด้วยทองแดง นอกจากนี้ยังสามารถปล่อยลูกศรและสายหวีของหนัง ในขณะที่ใช้งาน สามารถใช้สำหรับแทง กระแทก ตัด และฟัน ใช้เป็นโล่หรือเครื่องไถ... และเพื่อหลบฝน",
  str_pet_equip_intro_1602181 = "เชโอลได้รับของที่ระลึกทองคำที่มีค่านี้จากแม่ของเธอ สิ่งที่สำคัญที่สุดคือมันเข้ากันได้กับลูมินาของเชโอลอย่างมาก ทำให้เธอสามารถปล่อยพลังงานที่น่าทึ่งได้",
  str_pet_equip_intro_1602191 = "เหมือนกับว่ามันกำลังฉีกสายชีวิตสีแดงออกเป็นชิ้น ไม้เท้าทองคำกลายเป็นเกราะหนักที่ปกปิดความมืดและความรุนแรงได้ดีใต้ความสง่างาม การโจมตีของหนักมือไฟเหมือนรถม้าที่กำลังวิ่งชน และนี่คือเจ้าแห่งเงาที่แท้จริง",
  str_pet_equip_intro_1502201 = "กระเป๋าเป้ของเวอร์จิลเต็มไปด้วยอาหารอร่อย ๆ และชุดเครื่องมือประเมิน แต่เวอร์จิลได้ผสมผสานพวกมันในทางที่แปลกประหลาดเพื่อให้เขาสามารถใช้งานได้ตลอดเวลา เวอร์จิลอาจจะเป็นคนเดียวในโลกนี้ที่สามารถใช้พวกมันได้",
  str_pet_equip_intro_1602211 = "Bool เป็นนาโนหุ่นยนต์ที่อาศัยอยู่บน Algol และมีข่าวลือว่าได้ทำให้เจ้าของของมันเจ็บป่วยจากกระดูกและเอ็นที่หัก อย่างไรก็ตาม Bool จะกลายเป็นอย่างรุนแรงต่อสิ่งใดที่คุกคามการอยู่อาศัยของเจ้าของมัน",
  str_pet_equip_intro_1602231 = "เกล็ดแรกที่เฉินนี่หลุด ถูกเก็บรักษาเพื่อความสำคัญ ในฐานะพยานเงียบ ๆ ของประวัติศาสตร์หลงโจวและเฉินนี่ มันท่องเวลาผ่านพันปีไปด้วยเธอ ทุกครั้งที่เฉินนี่ใช้มันเพื่อแสดงรูปร่างที่แท้จริงของเธอ เกล็ดนี้จะมีรอยที่มองไม่เห็นของความทรงจำของเธอ",
  str_pet_equip_intro_1502241 = "เพื่อนของลัโว่ ซ่อง คือ ดิง ที่เป็นอสูรเสือที่ยังคงฝึกฝนทักษะของตน การฝึกฝนปัจจุบันของเขาเน้นที่การเพิ่มพูนทางกายภาพและการเจริญเติบโต ส่วนการคิดอย่างราบรื่นและพูดคุยอย่างชัดเจนเหมือนออโรเรียน นั้นเป็นเป้าหมายสำหรับอนาคต",
  str_pet_equip_intro_1602251 = "เคยเป็นหอกธรรมดาที่ทำจากไม้แอช แต่หลังจากที่เบธเลเฮมปรับปรุงและผสมผสานกับลูมินา มันสามารถปล่อยพลังที่มหาศาลในมือของเทียเร่ได้ ชาวเหนือเชื่อว่าหอกนี้มีพลังที่จะเรียกสายฟ้าและเรียกลม จึงตั้งชื่อมันว่า \"ผู้เรียกลม\" แต่ในความเป็นจริง เทียเร่ไม่เคยตั้งชื่อมันเลย",
  str_pet_equip_intro_1202261 = "เสียงกบที่น่าติดหูและได้รับการพิสูจน์ว่าเป็นประโยชน์ในฝัน แม้ว่าจะยากสำหรับเจ้าชายที่จะสร้างความประหลาดใจในชีวิตจริง แต่ความอบอุ่นและความเอื้อเฟื้อของมันจะเป็นแรงบันดาลใจให้เราเสมอ!",
  str_pet_equip_intro_1602271 = "ถ้าคุณเห็นโดรนวิ่งผ่านท้องฟ้าในขบวนการตายาว แรเชลน่าจะไม่ไกลห่าง สามตัวของอินทรีนักล่าที่ติดตามเธอในทุกภารกิจถูกปรับเปลี่ยนด้วยมือของเธอเอง แต่ละตัวสามารถทำงานสำรวจรอบคอบตลอดเวลา รวมถึงการสำรวจ การรบกวน การติดตาม และอื่น ๆ ความเร็วและประสิทธิภาพของพวกเขาไม่มีใครเทียบได้ในกองทัพของสหพันธรัฐอิลลูมินา",
  str_pet_equip_intro_1502281 = "\"โคนันผู้รู้ทุกสิ่ง\" เป็นการ์ตูนญี่ปุ่นเรื่องแรกที่เซต้าเคยอ่าน และยังเป็นตัวกระตุ้นที่ทำให้เธอหลงไหลในการเล่นเกมสวมบทบาท ด้วยเหตุผลนี้ เซต้ามักจะตั้งชื่อหุ่นยนต์ที่แข็งแกร่งที่สุดของเธอว่า \"โคนัน\" เพื่อเป็นการยกย่องซีรีส์ที่เธอชื่นชอบที่สุด",
  str_pet_equip_intro_1602291 = "คอนโซลเล็ก ๆ ที่สวยงามนี้ดูเหมือนจะเป็นรุ่นเดียวกับเครื่องเกมแรกของ Batia ถึงวันนี้ เธอยังคิดถึงคอนโซลรุ่นแรกที่เก่าเก็บที่เธอยังคิดถึงเป็นเพื่อนและครูแรกของเธอ",
  str_pet_equip_intro_1602301 = "เมื่อเธอได้รับพลังจากทางลับลึกลับ ไบเบิลโชกเลือดของวิกตอเรียก็เปิดออกอย่างกะทันหันและเปลี่ยนรูปร่างใหม่ คำทำนายไหลออกมาเหมือนน้ำตก ดูดซับความรู้ทั้งหมดเพื่อนำผู้นำการเปลี่ยนแปลงไปสู่ทางใหม่",
  str_pet_equip_intro_1602311 = "ด้ามดาบที่ดูเหมือนว่างเปล่า ตอนที่ถูกวิลเฮล์มจับ มันจะหยดเลือดที่รูปหล่อเป็นดาบ แนวคิดของดาบนี้คือ \"อำนาจ\" ชื่อจริงของมันคือ \"เครื่องมือสีเลือด\" แสงแดงที่รุนแรงทะลุผ่านเมฆและท้องฟ้า ทำให้ทุกอย่างที่อยู่ในทางของมันกระจายออกไปเหมือนกับกลีบดอกไม้ที่ร่วงลง",
  str_pet_equip_intro_1502321 = "อาจจะเป็นเพราะถูกบูชาจากเลือดแสนหายากโดยพระเจ้าแห่งสัจธรรม ตะปูแห่งศรัทธากลายเป็นดาบเลือดทรงกางเขน - ดาบเลือดศักดิ์สิทธิ์ มันทั้งเป็นการลงโทษและการช่วยชีวิตของเนลส์ ในนามของนักบุญ เนลส์ทิ่มแทงตัวเองด้วยมัน ปล่อยเลือดศักดิ์สิทธิ์เพื่อบริสุทธิ์โลก",
  str_pet_equip_intro_1602331 = "คทาที่ปล่อยแสงสว่างอย่างแรง แม้ว่าจะไม่ได้ใช้งาน มันยังคงส่องสว่างอย่างสวยงาม ถูกอาบแดดในแสงนี้ ไม่เพียงแค่ผู้ถือคทา แต่ยังรวมถึงคนที่อยู่รอบ ๆ ก็จะรู้สึกว่าหัวใจของพวกเขากำลังสว่างขึ้น",
  str_pet_equip_intro_1602341 = "ลูกศรที่มันยิงส่องสว่างเหมือนดวงดาวในความมืด จึงทำให้มันได้ชื่อนี้ ไม่มีใครอยากจะถูกเป้าหมายโดยธนูแบบนี้ในความมืดเลย",
  str_pet_equip_intro_1502351 = "กล่าวกันว่าดาบเล่มนี้มีความต้องการของมันเองและเลือกผู้ถือดาบ แม้แต่ผู้ที่มีทักษะที่สุดก็ไม่สามารถควบคุมมันได้หากไม่มีวิญญาณที่เป็นชนชั้นสูง",
  str_pet_equip_intro_1602371 = "หอยสังข์ที่สะอาดเรียบร้อยและสะท้อนแสง มีเพียงชนเผ่ามิราจเท่านั้นที่รู้วิธีการเล่น มันถูกกล่าวว่าเป็นส่วนต่อของกระดูกมิราจ เมื่อมายาเก็บมันขึ้นมา เธอเห็นสาระสำคัญของโลกอย่างชัดเจน และหัวใจของเธอเริ่มต้นเต้นตามจังหวะของบรรพบุรุษของเธอ\nโลกอาจจะเป็นแค่แฟนตาซี แต่แสงสว่างที่ยิ่งใหญ่ระหว่างช่วงเวลาที่สั้นๆนั้น มีค่าที่จะได้รับบทสรรเสริญที่สวยงาม",
  str_pet_equip_intro_1602381 = "ตราสัญลักษณ์ที่อคิลลีสมอบให้แก่แอนโทนี มันเต็มไปด้วยพลังที่มหาศาล เขาหวังอย่างจริงใจว่ามันจะช่วยเผ่าลองกินัสต่อสู้กับพรหมลิขิต แต่แต่ละรุ่นของเผ่าลองกินัสไม่สามารถทนทานที่จะใช้ตราสัญลักษณ์นี้ ทำให้มันยังคงเป็นเพียงสัญลักษณ์ของคำสาบานชนชั้นสูงของพวกเขา แม้มิทราก็จะใช้มันเพื่อเพิ่มพลังให้แก่ดาบของเธอเท่านั้น",
  str_pet_equip_name_1602411 = "เปลวไฟลุกโชน",
  str_pet_equip_intro_1602411 = "ลูมินาที่ติดตัวมาแต่เกิด; หัวใจที่เคลื่อนไหวอย่างเทียมทำที่ได้รับจากคณะกรรมการ; สัญลักษณ์ที่เก็บพลังงานที่วิกตอเรียมอบให้; พลังที่สามารถกลับคืนชีวิตที่ได้รับจากเจตภูต อูร์ซูรา... และหัวใจที่ไม่ยอมแพ้ของเปปิตาที่ยังเต้นแรงอยู่แม้นอกทรวงอก\nรวมกันแล้ว พวกเขาสร้างมิราเคิลนี้ขึ้นมา เมื่อเปปิตาจุดประกายพลังของหัวใจของตนเอง",
  str_pet_equip_name_1702361 = "แสงจันทร์ของลูดวีส",
  str_pet_equip_intro_1702361 = "ดาบยักษ์ที่ถูกสร้างขึ้นเฉพาะสำหรับเคลย์มอร์ ใบมีดมีรอยแผลจากการต่อสู้อย่างไม่รู้จบ แต่อาวุธที่ดูดุร้ายนี้ไม่เคยหันขอบมาที่ออโรเรียน ด้วยเหตุนี้แหล่งที่อคิลลีสตั้งชื่อมันตามชื่อเพื่อนที่อ่อนโยนของเขา—\nเป็นการยืนยันว่าใบมีดมีจุดประสงค์ที่แท้จริง: การป้องกัน",
